const Storage={async open(){try{db=await new Promise((res,rej)=>{const r=indexedDB.open('sanctum-local',1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('data'))r.result.createObjectStore('data')};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);r.onblocked=()=>rej(new Error('blocked'))})}catch{db=null}this.issue='';const candidates=[];let damaged=false;const accept=raw=>{if(!raw)return;try{candidates.push(validateState(raw))}catch{damaged=true;try{localStorage.setItem('sanctum-recovery',JSON.stringify(raw))}catch{}}};if(db)try{accept(await new Promise((res,rej)=>{const r=db.transaction('data').objectStore('data').get('state');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)}))}catch{damaged=true}try{accept(JSON.parse(localStorage.getItem('sanctum-fallback')||'null'))}catch{damaged=true}candidates.sort((a,b)=>b.revision-a.revision);if(damaged)this.issue=candidates.length?'Данные восстановлены из исправной локальной копии. Рекомендуем экспортировать резервную копию.':'Не удалось восстановить локальные данные. Импортируйте последнюю резервную копию.';if(candidates.length)return candidates[0];return freshState()},async write(){const snapshot=structuredClone(state);let ok=false;try{localStorage.setItem('sanctum-fallback',JSON.stringify(snapshot));ok=true}catch{}if(db)try{await new Promise((res,rej)=>{const tx=db.transaction('data','readwrite');tx.objectStore('data').put(snapshot,'state');tx.oncomplete=res;tx.onerror=()=>rej(tx.error);tx.onabort=()=>rej(tx.error)});ok=true}catch{}if(snapshot.revision===state.revision)$('#save-state').innerHTML=ok?'<i class="dot"></i> Сохранено':'Не сохранено';if(!ok)toast('Не удалось сохранить данные. Экспортируйте резервную копию.',true);return ok}};
