const XPSystem={required:level=>Math.round(100*Math.pow(level,1.38)),level(total){let level=1,currentXP=Math.max(0,total);while(currentXP>=this.required(level)&&level<10000){currentXP-=this.required(level);level++}return {level,currentXP,xpRequiredForNextLevel:this.required(level)}},mission(m){if(m.customXP!==null&&m.customXP!==undefined&&m.customXP!=='')return Math.round(Number(m.customXP));return Math.round(DIFFICULTIES[m.difficulty??2][1]*(1+Math.min(180,Math.max(0,Number(m.duration)||0))/180)*state.settings.xpMultiplier)},distribute(xp,allocations){const rows=allocations.filter(a=>state.attributes.some(s=>s.id===a.id));const sum=rows.reduce((n,a)=>n+Number(a.weight),0);if(!sum)return [];const out=rows.map(a=>({id:a.id,weight:a.weight,xp:Math.floor(xp*a.weight/sum),remainder:xp*a.weight/sum%1}));let left=xp-out.reduce((n,a)=>n+a.xp,0);[...out].sort((a,b)=>b.remainder-a.remainder).forEach(a=>{if(left>0){a.xp++;left--}});return out}};
const totalXP=()=>state.completions.reduce((s,c)=>s+c.xp,0)+state.brain.sessions.reduce((s,c)=>s+c.xp,0);
function recalcAttributes(){for(const a of state.attributes){a.history=[...state.completions,...state.brain.sessions].flatMap(c=>(c.allocations||[]).filter(x=>x.id===a.id).map(x=>({date:c.date,xp:x.xp,title:c.title,id:c.id})));a.totalXP=a.history.reduce((s,h)=>s+h.xp,0);Object.assign(a,XPSystem.level(a.totalXP))}}
function addActivity(title,type='system',xp=0,extra={}){state.activity.unshift({id:uid(),date:today(),time:new Date().toISOString(),title,type,xp,...extra})}
const completion=(id,date)=>state.completions.find(c=>c.missionId===id&&c.date===date);
function due(m,date){if(date<m.date)return false;if(!m.repeat||m.repeat==='none')return m.date===date;const days=Math.round((parseDate(date)-parseDate(m.date))/86400000);if(m.repeat==='daily')return true;if(m.repeat==='weekly')return days%7===0;if(m.repeat==='interval')return days%Math.max(1,m.interval||1)===0;if(m.repeat==='weekdays')return (m.weekdays||[]).includes(parseDate(date).getDay());return false}
function missionsOn(date){return state.missions.filter(m=>(!m.archived&&due(m,date))||completion(m.id,date))}
function missionStatus(m,date){if(completion(m.id,date))return 'completed';if(state.skipped.some(s=>s.missionId===m.id&&s.date===date))return 'skipped';return date<today()?'missed':'planned'}
const STATUSES={planned:'Запланирована',completed:'Выполнена',skipped:'Пропущена',missed:'Не выполнена'};
function streaks(){const dates=[...new Set([...state.completions,...state.brain.sessions].map(c=>c.date))].sort();let longest=0,run=0,last;for(const d of dates){run=last&&addDays(last,1)===d?run+1:1;longest=Math.max(longest,run);last=d}let current=0,d=dates.includes(today())?today():addDays(today(),-1);while(dates.includes(d)){current++;d=addDays(d,-1)}return {current,longest}}
const weekStart=(date=today())=>{const d=parseDate(date),first=Number(state.settings.startOfWeek);return addDays(date,-((d.getDay()-first+7)%7))};
function periodXP(from,to=today()){return [...state.completions,...state.brain.sessions].filter(c=>c.date>=from&&c.date<=to).reduce((s,c)=>s+c.xp,0)}
function toast(message,error=false,undo){const el=document.createElement('div');el.className='toast'+(error?' err':'');el.innerHTML=icon(error?'shield':'check')+`<span class="grow">${esc(message)}</span>`;if(undo){const b=document.createElement('button');b.textContent='Отменить';b.onclick=()=>{undo();el.remove()};el.append(b)}$('#toasts').append(el);setTimeout(()=>el.remove(),undo?10000:5500)}
const Modal={open(title,html,large=false){if(typeof BrainLab!=='undefined')BrainLab.stop();lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${large?'large':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Закрыть">${icon('close')}</button></div><div class="modal-body">${html}</div></section></div>`;document.body.style.overflow='hidden';setTimeout(()=>($('.modal input:not([type=hidden]),.modal select,.modal button')||$('.modal')).focus(),30)},close(){if(typeof BrainLab!=='undefined')BrainLab.stop();$('#modal-root').innerHTML='';document.body.style.overflow='';lastFocus?.focus?.()}};
