function beep(){if(!state.settings.sound)return;try{const ac=new(window.AudioContext||window.webkitAudioContext)(),osc=ac.createOscillator(),g=ac.createGain();osc.connect(g);g.connect(ac.destination);osc.frequency.setValueAtTime(520,ac.currentTime);osc.frequency.exponentialRampToValueAtTime(780,ac.currentTime+.1);g.gain.setValueAtTime(.045,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.24);osc.start();osc.stop(ac.currentTime+.25);osc.onended=()=>ac.close()}catch{}}
