const newMissionButton=()=>`<button class="btn primary" data-action="new-mission">${icon('plus',17)}<span class="desktop-text">Новая </span>миссия</button>`;
function empty(title,desc,action='new-mission',label='Создать миссию',ic='missions'){return `<div class="empty">${icon(ic,31)}<h3>${esc(title)}</h3><p>${esc(desc)}</p>${action?`<button class="btn" data-action="${action}">${icon('plus',15)}${esc(label)}</button>`:''}</div>`}
function renderMission(m,date=today()){const c=completion(m.id,date),status=missionStatus(m,date);return `<article class="mission ${c?'done':''}"><button class="check ${c?'done':''}" data-action="${c?'undo-mission':'complete-mission'}" data-id="${m.id}" data-date="${date}" aria-label="${c?'Отменить выполнение':'Выполнить миссию'}: ${esc(m.title)}" ${date>today()?'disabled':''}>${c?icon('check',15):''}</button><div class="grow"><button class="mission-title" data-action="edit-mission" data-id="${m.id}">${esc(m.title)}</button><div class="mission-meta"><span class="pill">${DIFFICULTIES[m.difficulty][0]}</span>${m.duration?`<span>${m.duration} мин</span>`:''}${m.allocations.slice(0,2).map(x=>{const a=state.attributes.find(a=>a.id===x.id);return a?`<span><i class="skill-dot" style="background:${a.accent}"></i>${esc(a.name)}</span>`:''}).join('')}${m.allocations.length>2?`<span>+${m.allocations.length-2}</span>`:''}${status==='missed'||status==='skipped'?`<span class="gold">${STATUSES[status]}</span>`:''}</div></div><div><div class="mission-xp">${c?'✓':'+'}${number(c?.xp??XPSystem.mission(m))} ОП</div><div class="mission-time">${m.time?fmtTime(m.time):'В течение дня'}</div></div><button class="icon-btn" data-action="mission-menu" data-id="${m.id}" data-date="${date}" aria-label="Действия с миссией ${esc(m.title)}">${icon('more',18)}</button></article>`}
function skillCard(a){return `<button class="skill-card" style="--c:${a.accent}" data-action="attribute-detail" data-id="${a.id}"><div class="flex between"><span class="skill-icon">${icon(a.icon,18)}</span><span class="pill">УР. ${a.level}</span></div><h3>${esc(a.name)}</h3><small>${esc(a.category)}</small><div class="bar" style="--p:${a.currentXP/a.xpRequiredForNextLevel*100}%;--c:${a.accent}"><i></i></div><div class="flex between"><small>${number(a.currentXP)} / ${number(a.xpRequiredForNextLevel)} ОП</small><small>${plural(a.history.length,'занятие','занятия','занятий')}</small></div></button>`}
function dailyChallenge(){const seed=[...today()].reduce((n,c)=>n*31+c.charCodeAt(0)>>>0,0)%5;const c=state.completions.filter(c=>c.date===today()),sessions=state.brain.sessions.filter(s=>s.date===today());return [{title:'Сложность — точка роста',desc:'Выполни одну миссию сложного уровня или выше.',target:1,value:c.filter(c=>c.difficulty>=3).length},{title:'Три шага ясности',desc:'Реши три новые логические задачи.',target:3,value:sessions.filter(s=>s.module==='logic'&&s.correct).length},{title:'Развивайся с разных сторон',desc:'Получи опыт в трёх разных атрибутах.',target:3,value:new Set([...c,...sessions].flatMap(c=>(c.allocations||[]).filter(a=>a.xp>0).map(a=>a.id))).size},{title:'Сто очков вперёд',desc:'Получи 100 очков опыта за сегодняшний день.',target:100,value:periodXP(today())},{title:'Время для себя',desc:'Удели миссиям 30 минут.',target:30,value:c.reduce((s,c)=>s+c.duration,0)}][seed]}
function renderActivity(items,emptyText='Здесь появятся твои первые достижения.'){return items.length?items.map(h=>`<div class="activity-item"><span class="activity-icon">${icon(h.type==='level'?'skills':h.type==='brain'?'brain':'check',14)}</span><div class="grow"><p>${esc(h.title)}</p><small>${fmtDate(h.date,true)}${h.xp?' · +'+number(h.xp)+' ОП':''}</small></div></div>`).join(''):`<p class="muted small" style="padding:13px 0">${emptyText}</p>`}
function renderDashboard(){const date=today(),ms=missionsOn(date),done=ms.filter(m=>completion(m.id,date)),xp=periodXP(date),level=XPSystem.level(totalXP()),daily=dailyChallenge(),streak=streaks().current;const visible=ms.filter(m=>missionFilter==='all'||(missionFilter==='completed'?completion(m.id,date):!completion(m.id,date))).sort((a,b)=>(a.time||'99').localeCompare(b.time||'99'));return intro('Твой следующий уровень.','Маленькие действия. Настоящие изменения.',newMissionButton(),parseDate(date).toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'}).toUpperCase())+`<div class="stats"><div class="stat"><div class="stat-label">${icon('bolt',15)}Опыт за сегодня</div><div class="stat-value">${number(xp)}<small>ОП</small></div><div class="stat-caption">${number(periodXP(weekStart()))} за эту неделю</div></div><div class="stat"><div class="stat-label">${icon('missions',15)}Миссии выполнены</div><div class="stat-value">${done.length}<small>/ ${ms.length}</small></div><div class="stat-caption">${ms.length?Math.round(done.length/ms.length*100):0}% дневного плана</div></div><div class="stat"><div class="stat-label">${icon('flame',15)}Серия активности</div><div class="stat-value">${streak}<small>дн.</small></div><div class="stat-caption">${streak?'Продолжай в своём ритме':'Сегодня — хорошее начало'}</div></div><div class="stat"><div class="stat-label">${icon('clock',15)}Время развития</div><div class="stat-value">${state.completions.filter(c=>c.date===date).reduce((s,c)=>s+c.duration,0)}<small>мин</small></div><div class="stat-caption">${plural(state.attributes.filter(a=>a.totalXP>0).length,'атрибут','атрибута','атрибутов')} в развитии</div></div></div><div class="dashboard-grid"><div class="stack"><section class="panel"><div class="panel-header"><div class="flex"><h2>Миссии на сегодня</h2><span class="pill">${ms.length}</span></div><a class="btn ghost" href="#/schedule">Расписание ${icon('arrow',15)}</a></div><div class="tabs"><button class="tab ${missionFilter==='all'?'active':''}" data-action="mission-filter" data-value="all">Все миссии</button><button class="tab ${missionFilter==='planned'?'active':''}" data-action="mission-filter" data-value="planned">В процессе</button><button class="tab ${missionFilter==='completed'?'active':''}" data-action="mission-filter" data-value="completed">Выполнены</button></div>${visible.length?visible.map(m=>renderMission(m)).join(''):empty(ms.length?'Всё спокойно':'Твой день начинается здесь',ms.length?'В этом списке пока нет миссий.':'Добавь первую миссию и направь энергию на то, что важно.')}<div class="panel-footer flex between"><span>${icon('target',13)} ${number(ms.reduce((s,m)=>s+XPSystem.mission(m),0))} ОП доступно сегодня</span><span>Твой темп. Твой путь.</span></div></section><section class="training-banner"><div class="training-icon">${icon('brain',25)}</div><div class="grow"><h3>Приведи разум в движение</h3><p>Короткая тренировка. Новый уровень ясности.</p></div><button class="btn" data-action="train-random">Тренировать меня ${icon('arrow',16)}</button></section><section><div class="flex between" style="margin:3px 0 15px"><h2 style="font-size:17px">Атрибуты в развитии</h2><a href="#/matrix" class="btn ghost" style="font-size:12px">Карта навыков ${icon('arrow',15)}</a></div><div class="skills-grid">${state.attributes.filter(a=>!a.archived).slice(0,6).map(skillCard).join('')||empty('С чего начнём?','Выбери качество, которое хочешь развить.','new-attribute','Добавить атрибут')}</div></section></div><aside class="stack dashboard-aside"><section class="panel profile-card"><div class="panel-header"><span class="eyebrow">Профиль развития</span>${icon('shield',16)}</div><div class="ring"><svg width="144" height="144" viewBox="0 0 144 144"><circle cx="72" cy="72" r="64" fill="none" stroke="#283a3b" stroke-width="3"/><circle cx="72" cy="72" r="64" fill="none" stroke="var(--accent)" stroke-width="3" stroke-dasharray="${Math.max(4,level.currentXP/level.xpRequiredForNextLevel*402)} 402" stroke-linecap="round"/><circle cx="72" cy="72" r="54" fill="none" stroke="#2b3d3d" stroke-width="1" stroke-dasharray="1 9"/></svg><div class="ring-center"><strong>${level.level.toString().padStart(2,'0')}</strong><div>УРОВЕНЬ</div></div></div><h3>${esc(state.profile.name)}</h3><p>${esc(rankFor())}</p>${state.profile.title&&state.profile.title!=='В начале пути'?`<p class="dim" style="font-size:12px">${esc(state.profile.title)}</p>`:''}<div class="profile-foot"><div class="flex between"><span>${number(level.currentXP)} / ${number(level.xpRequiredForNextLevel)} ОП</span><span>Уровень ${level.level+1}</span></div><div class="bar" style="--p:${level.currentXP/level.xpRequiredForNextLevel*100}%"><i></i></div><p style="margin-top:14px;font-size:11px">${number(totalXP())} очков опыта за всё время</p></div></section><section class="panel daily"><div class="flex between"><span class="eyebrow">Вызов дня</span>${icon('sun',17)}</div><h3>${daily.title}</h3><p>${daily.desc}</p><div class="bar" style="--c:var(--gold);--p:${Math.min(100,daily.value/daily.target*100)}%"><i></i></div><div class="flex between" style="font-size:11px"><span class="dim">${Math.min(daily.value,daily.target)} / ${daily.target}</span><span class="gold">${daily.value>=daily.target?'Вызов принят ✓':'До конца дня'}</span></div></section><section class="panel pad"><div class="flex between"><h3>Последние события</h3><a href="#/history" aria-label="Вся история" class="icon-btn">${icon('arrow',16)}</a></div>${renderActivity(state.activity.slice(0,3))}</section></aside></div>`}
function render(){renderNav();const views={overview:renderDashboard,today:typeof renderToday==='function'?renderToday:renderDashboard};const extended=typeof extraViews!=='undefined'?extraViews:{};$('#main').innerHTML=(extended[route]||views[route]||renderDashboard)()+`<footer class="footer"><span>SANCTUM · ТВОЁ ПРОСТРАНСТВО РАЗВИТИЯ</span><span>${icon('lock',11)} Локальное хранение · Без отвлечений</span></footer>`;bindView()}
function navigate(){route=location.hash.replace('#/','').split('?')[0]||'overview';if(!NAV.some(n=>n[0]===route))route='overview';if(typeof BrainLab!=='undefined')BrainLab.stop();Modal.close();render();window.scrollTo(0,0)}
function validateState(raw){return validateStateStrict(raw)}
const LOGIC_PUZZLES=[{"id":"logic-01","title":"Ступени света","question":"В первом зале горят 3 огня. В каждом следующем зале огней больше: сначала на 2, затем на 4, затем на 6 и далее на следующие чётные числа. Сколько огней в пятом зале?","options":["21","23","24","25"],"answer":1,"explanation":"Число огней растёт так: 3 → 5 → 9 → 15 → 23. Перед пятым залом нужно прибавить 8.","difficulty":"Лёгкая","category":"Числовые закономерности"},{"id":"logic-02","title":"Два действия","question":"Начиная с 2, к числу по очереди применяют два действия: умножить на 3, вычесть 2. Получается 2, 6, 4, 12, 10. Какое число следующее?","options":["30","28","12","8"],"answer":0,"explanation":"После вычитания 2 снова наступает очередь умножения на 3: 10 × 3 = 30.","difficulty":"Лёгкая","category":"Числовые закономерности"},{"id":"logic-03","title":"Удвоенный запас","question":"У хранителя сначала 1 кристалл. Каждый вечер он удваивает весь запас и добавляет ещё 1 кристалл. Каким станет запас после пяти вечеров?","options":["31","32","64","63"],"answer":3,"explanation":"После каждого вечера запас равен 3, 7, 15, 31 и 63 кристаллам соответственно.","difficulty":"Средняя","category":"Числовые закономерности"},{"id":"logic-04","title":"Эхо двух чисел","question":"Первые два числа равны 2 и 5. Каждое следующее равно сумме двух предыдущих. Какое число стоит на шестом месте?","options":["24","29","31","38"],"answer":2,"explanation":"Первые шесть чисел: 2, 5, 7, 12, 19, 31. Последнее получено как 12 + 19.","difficulty":"Лёгкая","category":"Числовые закономерности"},{"id":"logic-05","title":"Две дорожки","question":"В ряду 5, 20, 8, 18, 11, 16 числа на нечётных местах каждый раз увеличиваются на 3, а числа на чётных уменьшаются на 2. Какое число будет седьмым?","options":["13","14","15","18"],"answer":1,"explanation":"Седьмое место нечётное. На нечётных местах стоят 5, 8, 11, поэтому следующим будет 11 + 3 = 14.","difficulty":"Средняя","category":"Числовые закономерности"},{"id":"logic-06","title":"Тихий отсчёт","question":"От 30 последовательно вычитают 1, затем 2, затем 3 и так далее. После нескольких действий получен ряд 30, 29, 27, 24, 20. Какое число идёт дальше?","options":["15","14","16","17"],"answer":0,"explanation":"Последнее выполненное действие — вычитание 4. Следующее — вычитание 5: 20 − 5 = 15.","difficulty":"Лёгкая","category":"Числовые закономерности"},{"id":"logic-07","title":"Пробуждение маяков","question":"В первый день горит 1 маяк. Каждый следующий день общее число горящих маяков ровно втрое больше, чем накануне. Сколько маяков горит в пятый день?","options":["15","27","243","81"],"answer":3,"explanation":"Между первым и пятым днями четыре перехода: 1 → 3 → 9 → 27 → 81.","difficulty":"Лёгкая","category":"Числовые закономерности"},{"id":"logic-08","title":"Повторяющийся ритм","question":"К числу 0 прибавляют 1, затем 2, затем 3, после чего этот цикл из трёх прибавлений повторяют. Получается 0, 1, 3, 6, 7, 9. Какое число следующее?","options":["10","11","12","13"],"answer":2,"explanation":"После прибавления 2 в повторяющемся цикле идёт прибавление 3: 9 + 3 = 12.","difficulty":"Лёгкая","category":"Числовые закономерности"},{"id":"logic-09","title":"Печать архива","question":"Каждый ящик на чердаке запечатан. Других сведений нет. Какое утверждение обязательно верно?","options":["Каждый запечатанный ящик находится на чердаке.","Незапечатанный ящик не находится на чердаке.","На чердаке находится хотя бы один ящик.","Вне чердака нет запечатанных ящиков."],"answer":1,"explanation":"Если бы незапечатанный ящик находился на чердаке, он нарушал бы исходное правило. Обратное утверждение и существование ящиков из правила не следуют.","difficulty":"Средняя","category":"Логические выводы"},{"id":"logic-10","title":"Беззвучный колокол","question":"Известно правило: если колокол звучит, дверь открыта. Сейчас дверь закрыта. Что можно заключить?","options":["Сейчас колокол не звучит.","Сейчас колокол звучит.","Дверь никогда не открывалась.","Колокол сломан."],"answer":0,"explanation":"Звучащий колокол требовал бы открытой двери. Поскольку дверь закрыта, колокол сейчас не звучит. О его исправности сведений нет.","difficulty":"Лёгкая","category":"Логические выводы"},{"id":"logic-11","title":"Одна верная табличка","question":"Ключ лежит ровно в одном из трёх ящиков: А, Б или В. Табличка А говорит: «Ключ в Б». Табличка Б: «Ключ не в Б». Табличка В: «Ключ не в А». Верна ровно одна табличка. Где ключ?","options":["В ящике Б","В ящике В","Условие не позволяет выбрать ящик","В ящике А"],"answer":3,"explanation":"Таблички А и Б противоположны, поэтому из них всегда верна ровно одна. Значит, табличка В должна быть ложной: ключ находится в А.","difficulty":"Средняя","category":"Логические выводы"},{"id":"logic-12","title":"Две верные записи","question":"На столе лежит ровно один камень: красный, синий или зелёный. Сделаны три записи: «Он красный», «Он не синий», «Он не красный». Ровно две записи верны. Какой цвет точно исключён?","options":["Красный","Зелёный","Синий","Нельзя исключить ни один цвет"],"answer":2,"explanation":"Первая и третья записи противоположны: одна из них верна. Для двух верных записей вторая тоже должна быть верной, значит, камень не синий. Красный и зелёный подходят.","difficulty":"Средняя","category":"Логические выводы"},{"id":"logic-13","title":"Янтарные камни","question":"Все янтарные камни тёплые. Ни один тёплый камень не плавает. Какой вывод обязательно верен?","options":["Все неплавающие камни янтарные.","Ни один янтарный камень не плавает.","Все камни тёплые.","Каждый холодный камень плавает."],"answer":1,"explanation":"Янтарные камни входят в группу тёплых, а у всех тёплых камней исключено плавание. Остальные выводы требуют дополнительных сведений.","difficulty":"Лёгкая","category":"Логические выводы"},{"id":"logic-14","title":"Карты странников","question":"Некоторые странники — картографы. Каждый картограф умеет рисовать карты. Что из этого обязательно следует?","options":["Хотя бы один странник умеет рисовать карты.","Все странники умеют рисовать карты.","Любой рисующий карты — странник.","Ни один странник не рисует карты."],"answer":0,"explanation":"Существует хотя бы один странник-картограф. По второму условию этот странник умеет рисовать карты. Про всех остальных странников ничего не сказано.","difficulty":"Лёгкая","category":"Логические выводы"},{"id":"logic-15","title":"Свежие листья","question":"Если растение полили утром, к полудню его листья свежие. К полудню листья свежие. Других правил нет. Можно ли определить, поливали ли растение утром?","options":["Да, его обязательно поливали.","Да, его точно не поливали.","Условия противоречат друг другу.","Нет, возможны оба варианта."],"answer":3,"explanation":"Правило даёт достаточное условие свежести, но не единственную возможную причину. Свежие листья совместимы и с поливом, и с его отсутствием.","difficulty":"Средняя","category":"Логические выводы"},{"id":"logic-16","title":"Право входа","question":"В зал разрешено входить только обладателям жетона. Лев вошёл в зал, не нарушив правила. Что точно известно?","options":["Лев был единственным посетителем.","Каждый обладатель жетона уже вошёл.","При входе у Льва был жетон.","Лев сам изготовил жетон."],"answer":2,"explanation":"Слово «только» делает наличие жетона необходимым условием разрешённого входа. Лев вошёл по правилам, следовательно, жетон у него был.","difficulty":"Лёгкая","category":"Логические выводы"},{"id":"logic-17","title":"Белый кристалл","question":"В непрозрачном мешочке 3 белых и 2 чёрных кристалла. Каждый из пяти кристаллов одинаково вероятно достать первым. Какова вероятность достать белый?","options":["2/5","3/5","1/2","1/5"],"answer":1,"explanation":"Белых кристаллов 3 из 5. Вероятность равна числу подходящих исходов, делённому на общее число равновероятных исходов: 3/5.","difficulty":"Лёгкая","category":"Вероятность"},{"id":"logic-18","title":"Два жетона судьбы","question":"Два независимых броска честного двустороннего жетона дают либо солнце, либо луну с равными вероятностями. Какова вероятность получить ровно одно солнце?","options":["1/2","1/4","3/4","1"],"answer":0,"explanation":"Есть четыре равновероятных исхода: солнце–солнце, солнце–луна, луна–солнце и луна–луна. Подходят два из четырёх, то есть 1/2.","difficulty":"Лёгкая","category":"Вероятность"},{"id":"logic-19","title":"Высокая грань","question":"Бросают честный шестигранный кубик с числами от 1 до 6. Какова вероятность получить число строго больше 4?","options":["1/6","1/2","2/3","1/3"],"answer":3,"explanation":"Подходят только 5 и 6: это две грани из шести. Получаем 2/6 = 1/3.","difficulty":"Лёгкая","category":"Вероятность"},{"id":"logic-20","title":"Чётная сумма","question":"Из четырёх карточек с числами 1, 2, 3 и 4 случайно выбирают две разные карточки. Все пары равновероятны. Какова вероятность, что сумма чисел чётная?","options":["1/2","2/3","1/3","1/4"],"answer":2,"explanation":"Всего 6 пар. Чётная сумма возникает у двух нечётных или двух чётных чисел: подходят пары {1, 3} и {2, 4}. Вероятность 2/6 = 1/3.","difficulty":"Средняя","category":"Вероятность"},{"id":"logic-21","title":"Кристалл возвращается","question":"В мешочке 2 красных и 1 синий кристалл. Случайно достают один кристалл, возвращают его, перемешивают и снова достают один. Каждый кристалл при каждом выборе равновероятен. Какова вероятность дважды достать красный?","options":["1/3","4/9","2/3","2/9"],"answer":1,"explanation":"Благодаря возвращению кристалла вероятность красного при каждом независимом выборе равна 2/3. Для двух красных: 2/3 × 2/3 = 4/9.","difficulty":"Средняя","category":"Вероятность"},{"id":"logic-22","title":"Выбор шкатулки","question":"В первой шкатулке 2 красных камня, во второй — 1 красный и 1 синий. Сначала выбирают шкатулку с равными вероятностями, затем случайный камень из неё. Какова вероятность достать синий камень?","options":["1/4","1/2","1/3","3/4"],"answer":0,"explanation":"Синий можно достать только из второй шкатулки. Вероятность выбрать её равна 1/2, а затем выбрать синий — ещё 1/2. Итог: 1/4.","difficulty":"Средняя","category":"Вероятность"},{"id":"logic-23","title":"Середина ряда","question":"Три разные карточки с числами 1, 2 и 3 перемешивают и раскладывают в ряд. Все порядки равновероятны. Какова вероятность, что карточка 2 окажется посередине?","options":["1/6","1/2","2/3","1/3"],"answer":3,"explanation":"Карточка 2 с одинаковой вероятностью занимает каждое из трёх мест. Также можно посчитать: из 6 порядков подходят 2, что даёт 1/3.","difficulty":"Лёгкая","category":"Вероятность"},{"id":"logic-24","title":"Хотя бы одна шестёрка","question":"Честный шестигранный кубик бросают дважды независимо. Какова вероятность, что хотя бы один раз выпадет 6?","options":["1/3","1/36","11/36","5/18"],"answer":2,"explanation":"Вероятность ни разу не получить 6 равна 5/6 × 5/6 = 25/36. Вычитаем её из 1: 1 − 25/36 = 11/36.","difficulty":"Сложная","category":"Вероятность"},{"id":"logic-25","title":"Три места у окна","question":"Анна, Борис и Вера заняли три места в ряд, по одному человеку на место. Анна сидит не с краю. Борис сидит левее Веры. Кто сидит справа?","options":["Анна","Вера","Борис","Определить невозможно"],"answer":1,"explanation":"Анна занимает середину. Борис и Вера занимают края, причём Борис левее Веры. Порядок слева направо: Борис, Анна, Вера.","difficulty":"Лёгкая","category":"Ограничения"},{"id":"logic-26","title":"Порядок обрядов","question":"Нужно выполнить четыре разных действия по одному разу: зажечь огонь, открыть книгу, прочитать строку, ударить в гонг. Огонь зажигают до открытия книги, книгу открывают до чтения, а в гонг ударяют непосредственно перед зажиганием огня. Что выполняют первым?","options":["Ударяют в гонг","Зажигают огонь","Открывают книгу","Читают строку"],"answer":0,"explanation":"Гонг должен стоять непосредственно перед огнём, затем по условиям идут книга и чтение. Единственный порядок: гонг → огонь → книга → строка.","difficulty":"Средняя","category":"Ограничения"},{"id":"logic-27","title":"Трёхзначная печать","question":"Код состоит из цифр 1, 2 и 3, каждая встречается ровно один раз. Последняя цифра равна сумме первых двух, а первая меньше второй. Какой это код?","options":["213","132","231","123"],"answer":3,"explanation":"Только 3 равна сумме двух остальных цифр: 1 + 2. Значит, 3 стоит последней. Условие «первая меньше второй» оставляет порядок 1, 2, 3.","difficulty":"Лёгкая","category":"Ограничения"},{"id":"logic-28","title":"Запасы двух хранителей","question":"У двух хранителей вместе 24 камня. У старшего ровно вдвое больше камней, чем у младшего. Сколько камней у старшего?","options":["8","12","16","18"],"answer":2,"explanation":"Пусть у младшего одна доля, тогда у старшего две. Всего три доли равны 24, одна доля равна 8, а две — 16.","difficulty":"Лёгкая","category":"Ограничения"},{"id":"logic-29","title":"Перепутанные надписи","question":"В трёх коробках лежат: только яблоки, только груши, смесь яблок и груш. На коробках надписи «Яблоки», «Груши», «Смесь», и каждая неверна. Из коробки «Смесь» достали яблоко. Что находится в коробке «Груши»?","options":["Только яблоки","Смесь яблок и груш","Только груши","Определить невозможно"],"answer":1,"explanation":"Коробка «Смесь» не может содержать смесь, а вынутое яблоко означает, что там только яблоки. Для коробки «Груши» остались груши или смесь, но её надпись неверна, значит, там смесь.","difficulty":"Сложная","category":"Ограничения"},{"id":"logic-30","title":"Число между границами","question":"Задумано целое число от 20 до 50 включительно. Оно делится без остатка и на 3, и на 5, а также является нечётным. Какое это число?","options":["45","25","30","35"],"answer":0,"explanation":"Число должно быть кратно 15. В заданном промежутке подходят 30 и 45; нечётным из них является только 45.","difficulty":"Средняя","category":"Ограничения"},{"id":"logic-31","title":"Три сигнальных огня","question":"Есть красный, синий и зелёный огни. Горят ровно два. Если горит красный, обязательно горит синий. Синий и зелёный никогда не горят вместе. Какой огонь сейчас выключен?","options":["Красный","Синий","Определить невозможно","Зелёный"],"answer":3,"explanation":"Пара «синий и зелёный» запрещена. Пара «красный и зелёный» тоже невозможна: красный потребовал бы ещё и синий, а горят ровно два. Остаются красный и синий.","difficulty":"Средняя","category":"Ограничения"},{"id":"logic-32","title":"Путь через четыре зала","question":"Путник посещает четыре зала А, Б, В и Г, каждый ровно один раз. Он начинает в А, заканчивает в Г и входит в В непосредственно после Б. Какой зал он посещает вторым?","options":["Зал А","Зал В","Зал Б","Зал Г"],"answer":2,"explanation":"Начало и конец уже заданы. Два средних места должны занять Б и В именно в таком порядке: А → Б → В → Г.","difficulty":"Лёгкая","category":"Ограничения"},{"id":"logic-33","title":"Две цифры замка","question":"Двузначный код состоит из двух цифр. Их сумма равна 11. Первая цифра на 3 больше второй. Какой код нужен?","options":["47","74","83","65"],"answer":1,"explanation":"Вычтем разницу цифр из их суммы: 11 − 3 = 8. Это удвоенная вторая цифра, поэтому она равна 4. Первая на 3 больше: 7. Получается 74.","difficulty":"Средняя","category":"Ограничения"},{"id":"logic-34","title":"Одежда странника","question":"У странника 3 разные накидки и 2 разных пояса. Для выхода он выбирает ровно одну накидку и один пояс. Сколько разных сочетаний возможно?","options":["6","5","8","9"],"answer":0,"explanation":"К каждой из трёх накидок подходят два выбора пояса. По правилу произведения всего 3 × 2 = 6 сочетаний.","difficulty":"Лёгкая","category":"Комбинаторика"},{"id":"logic-35","title":"Пара рун","question":"Есть 5 разных рун. Нужно выбрать ровно 2 разные руны; порядок выбора не имеет значения. Сколько существует пар?","options":["5","20","25","10"],"answer":3,"explanation":"Первую руну можно выбрать 5 способами, вторую — 4. В таком подсчёте каждая пара учтена дважды, поэтому 5 × 4 / 2 = 10.","difficulty":"Средняя","category":"Комбинаторика"},{"id":"logic-36","title":"Короткий маршрут","question":"Чтобы добраться до цели по сетке, нужно сделать ровно 2 шага вправо и 1 шаг вверх в любом порядке. Другие шаги запрещены. Сколько разных последовательностей шагов возможно?","options":["2","4","3","6"],"answer":2,"explanation":"Единственный шаг вверх можно поставить первым, вторым или третьим. Получаются три маршрута: вверх–вправо–вправо, вправо–вверх–вправо и вправо–вправо–вверх.","difficulty":"Лёгкая","category":"Комбинаторика"},{"id":"logic-37","title":"Четыре символа","question":"Четыре разные каменные плитки нужно поставить в ряд, используя каждую ровно один раз. Сколько разных порядков возможно?","options":["12","24","16","32"],"answer":1,"explanation":"Первое место можно заполнить 4 способами, второе — 3, третье — 2, последнее — 1. Всего 4 × 3 × 2 × 1 = 24.","difficulty":"Средняя","category":"Комбинаторика"},{"id":"logic-38","title":"Не оставлять зал в темноте","question":"У трёх разных ламп отдельные выключатели. Каждая лампа может быть включена или выключена. Сколько состояний освещения возможно, если хотя бы одна лампа должна гореть?","options":["7","3","6","8"],"answer":0,"explanation":"Без ограничения имеется 2 × 2 × 2 = 8 состояний. Исключаем единственное состояние, в котором все лампы выключены, и получаем 7.","difficulty":"Средняя","category":"Комбинаторика"},{"id":"logic-39","title":"Чётный пропуск","question":"Из цифр 1, 2, 3 и 4 составляют двузначные чётные числа. Цифры в одном числе не повторяются. Сколько таких чисел?","options":["4","8","12","6"],"answer":3,"explanation":"Последней цифрой может быть только 2 или 4. Для каждого из этих двух вариантов первая цифра выбирается тремя способами. Итого 2 × 3 = 6.","difficulty":"Средняя","category":"Комбинаторика"},{"id":"logic-40","title":"Встречи хранителей","question":"Четыре хранителя проводят беседы: каждый беседует с каждым другим ровно один раз наедине. Сколько всего бесед состоится?","options":["4","8","6","12"],"answer":2,"explanation":"Каждая беседа соответствует паре хранителей. Есть 4 × 3 / 2 = 6 пар; деление на 2 устраняет повторный подсчёт одной беседы с двух сторон.","difficulty":"Лёгкая","category":"Комбинаторика"},{"id":"logic-41","title":"Круг из шести рун","question":"Шесть разных рун размещают по окружности. Расположения, получаемые только поворотом всего круга, считаются одинаковыми. Зеркальные отражения считаются разными. Сколько расположений возможно?","options":["60","120","360","720"],"answer":1,"explanation":"Зафиксируем одну руну как начало отсчёта, убрав различия из-за поворотов. Остальные пять можно разместить 5 × 4 × 3 × 2 × 1 = 120 способами. На 2 не делим, поскольку отражения различаются.","difficulty":"Сложная","category":"Комбинаторика"},{"id":"logic-42","title":"Нижняя грань","question":"У куба противоположны следующие пары граней: красная и синяя, зелёная и жёлтая, белая и чёрная. Куб поставили чёрной гранью вверх. Какая грань снизу?","options":["Белая","Красная","Зелёная","Синяя"],"answer":0,"explanation":"Верхняя и нижняя грани куба противоположны. По условию чёрной грани противоположна белая.","difficulty":"Лёгкая","category":"Пространственное мышление"},{"id":"logic-43","title":"Повороты в коридоре","question":"Путник смотрит на север. Он поворачивается на 90° вправо, затем на 90° влево, затем ещё на 90° влево. Куда он смотрит в конце?","options":["На север","На восток","На юг","На запад"],"answer":3,"explanation":"Последовательность направлений: север → восток → север → запад. Последний поворот влево от севера ведёт на запад.","difficulty":"Лёгкая","category":"Пространственное мышление"},{"id":"logic-44","title":"Зеркальная стрелка","question":"На плоскости нарисована горизонтальная стрелка, направленная вправо. Её отражают относительно вертикальной прямой на той же плоскости. Куда направлена отражённая стрелка?","options":["Вправо","Вверх","Влево","Вниз"],"answer":2,"explanation":"Отражение относительно вертикальной прямой меняет левое и правое направления местами. Горизонтальная стрелка остаётся горизонтальной и направляется влево.","difficulty":"Лёгкая","category":"Пространственное мышление"},{"id":"logic-45","title":"Квадраты мозаики","question":"Квадрат разбит на сетку 4 × 4 из одинаковых маленьких квадратов. Сколько всего квадратов любого размера образовано линиями этой сетки? Считайте только квадраты со сторонами вдоль линий сетки.","options":["16","30","25","40"],"answer":1,"explanation":"Квадратов со стороной в 1 клетку — 16, в 2 клетки — 9, в 3 клетки — 4, в 4 клетки — 1. Всего 16 + 9 + 4 + 1 = 30.","difficulty":"Сложная","category":"Пространственное мышление"},{"id":"logic-46","title":"Четыре слоя","question":"Прямоугольный лист складывают пополам, затем ещё раз пополам так, что получаются 4 полностью совпадающих слоя. Внутри сложенной фигуры, вдали от всех сгибов и краёв, делают один прокол насквозь. Сколько отверстий будет в полностью развёрнутом листе?","options":["4","1","2","8"],"answer":0,"explanation":"Прокол проходит через четыре слоя, которые после разворачивания становятся четырьмя разными участками листа. Отступ от сгибов исключает совпадение отверстий.","difficulty":"Средняя","category":"Пространственное мышление"},{"id":"logic-47","title":"Окрашенные рёбра","question":"Большой куб составлен из 27 одинаковых маленьких кубиков в виде 3 × 3 × 3. Всю внешнюю поверхность большого куба покрасили. У скольких маленьких кубиков окрашены ровно две грани?","options":["8","6","18","12"],"answer":3,"explanation":"Две окрашенные грани имеют кубики на рёбрах, кроме углов. На каждом из 12 рёбер куба 3 × 3 × 3 находится ровно один такой кубик. Значит, их 12.","difficulty":"Сложная","category":"Пространственное мышление"},{"id":"logic-48","title":"Место в забеге","question":"В забеге без круговых обгонов вы обогнали участника, который непосредственно перед обгоном занимал второе место. За это время других обгонов не было. Какое место вы теперь занимаете?","options":["Первое","Третье","Второе","Определить невозможно"],"answer":2,"explanation":"Вы заняли место обогнанного участника — второе. Участник на первом месте по условию остался впереди.","difficulty":"Лёгкая","category":"Нестандартное мышление"},{"id":"logic-49","title":"Разница возрастов","question":"Сумма возрастов двух хранителей сейчас равна 46 годам. Старший ровно на 28 лет старше младшего. Сколько лет младшему?","options":["18","9","14","23"],"answer":1,"explanation":"Если вычесть разницу возрастов из суммы, останется удвоенный возраст младшего: 46 − 28 = 18. Поэтому младшему 18 / 2 = 9 лет.","difficulty":"Средняя","category":"Нестандартное мышление"},{"id":"logic-50","title":"Одна общая сестра","question":"В одной семье четверо братьев. У каждого из них ровно одна сестра, и это одна и та же девочка. Других детей в семье нет. Сколько детей в семье?","options":["5","4","8","9"],"answer":0,"explanation":"Четыре брата имеют одну общую сестру. Она не становится отдельным человеком для каждого брата: всего 4 + 1 = 5 детей.","difficulty":"Лёгкая","category":"Нестандартное мышление"},{"id":"logic-51","title":"Один фонарь на троих","question":"Трое путников переходят мост за 1, 3 и 7 минут соответственно. Мост выдерживает не более двух человек. Любой переход в любую сторону требует единственного фонаря; бросать или передавать его через мост нельзя. Пара движется со скоростью более медленного. Все начинают на одном берегу. Какое минимальное время нужно, чтобы все оказались на другом?","options":["10 минут","12 минут","14 минут","11 минут"],"answer":3,"explanation":"Переходят путники за 1 и 3 минуты: 3 минуты. Быстрый возвращается: 1 минута. Затем переходят путники за 1 и 7 минут: 7 минут. Итого 11. При одном возвращении остальные варианты дают не меньше; дополнительные переходы только увеличивают время.","difficulty":"Сложная","category":"Нестандартное мышление"},{"id":"logic-52","title":"Две неровные нити","question":"Каждая из двух нитей полностью сгорает за 80 минут при поджигании с одного конца, но горит неравномерно. Можно одновременно поджигать любые концы. Вначале первую нить подожгли с двух концов, вторую — с одного. Как отмерить ровно 60 минут от начала?","options":["Дождаться сгорания первой нити и закончить отсчёт.","Дождаться сгорания второй нити, ничего не меняя.","Когда первая сгорит, поджечь второй конец второй нити и дождаться её сгорания.","Сразу поджечь обе нити с двух концов и дождаться их сгорания."],"answer":2,"explanation":"Первая нить с двумя фронтами огня сгорит за 40 минут. У второй останется 40 минут горения с одного конца. Если тогда поджечь её второй конец, остаток сгорит за 20 минут. Всего 40 + 20 = 60.","difficulty":"Сложная","category":"Нестандартное мышление"},{"id":"logic-53","title":"Тяжёлая печать","question":"Есть 27 одинаковых на вид печатей. Ровно одна тяжелее остальных, остальные весят одинаково. Доступны чашечные весы без гирь, у которых три исхода: левая чаша тяжелее, правая тяжелее, равновесие. Сколько взвешиваний достаточно и необходимо в худшем случае, чтобы найти тяжёлую печать?","options":["2","3","4","9"],"answer":1,"explanation":"Делим 27 печатей на три группы по 9 и сравниваем две группы. Нужная группа определяется одним взвешиванием. Затем так же выбираем 3 из 9 и 1 из 3. Двух взвешиваний недостаточно: они дают не более 3² = 9 разных цепочек результатов для 27 кандидатов.","difficulty":"Сложная","category":"Нестандартное мышление"},{"id":"logic-54","title":"Обмен пустых сосудов","question":"У вас 9 пустых сосудов. За каждые 3 пустых можно получить 1 полный. Выпив его, вы снова получаете 1 пустой сосуд. Брать сосуды в долг нельзя. Какое наибольшее число полных сосудов можно получить и выпить?","options":["4","3","5","6"],"answer":0,"explanation":"Сначала 9 пустых обмениваются на 3 полных. После питья остаются 3 пустых, которые обмениваются ещё на 1 полный. После него остаётся 1 пустой — для нового обмена недостаточно. Всего 4.","difficulty":"Средняя","category":"Нестандартное мышление"},{"id":"logic-55","title":"Тепло за закрытой дверью","question":"Три выключателя с номерами 1, 2 и 3 управляют тремя разными лампами в закрытой комнате, каждый — своей. Изначально все лампы выключены и холодны. Включённая лампа нагревается, а после выключения достаточно долго остаётся тёплой. Вы включили 1, дождались нагрева его лампы, выключили 1, включили 2 и сразу вошли. Какому выключателю соответствует холодная выключенная лампа?","options":["Выключателю 1","Выключателю 2","Определить невозможно","Выключателю 3"],"answer":3,"explanation":"Лампа выключателя 1 выключена, но ещё тёплая. Лампа выключателя 2 горит. Только лампа выключателя 3 не включалась и поэтому остаётся выключенной и холодной.","difficulty":"Средняя","category":"Нестандартное мышление"}];
const DETECTIVE_CASES=[{"id":"case-01","title":"Пропавший жетон","question":"В вымышленном музее из комнаты пропал памятный жетон. Кто из посетителей мог забрать его в установленный промежуток?","options":["Анна","Борис","Вера","Глеб"],"answer":1,"explanation":"В 18:04 жетон ещё лежал на столе, а в 18:12 уже исчез. Только Борис находился в комнате внутри этого промежутка. Анна ушла раньше последней проверки, Вера пришла позже обнаружения пропажи, Глеб не входил. Вывод касается возможности взять жетон; сам журнал ещё не доказывает кражу.","difficulty":"Лёгкая","category":"Временная линия","clues":["Сотрудник лично проверил наличие жетона в 18:04 и обнаружил пропажу в 18:12.","Единственная дверь автоматически записывает все входы и выходы; других проходов нет.","Анна была внутри с 18:01 до 18:03, Борис — с 18:07 до 18:09, Вера — с 18:15 до 18:17.","Глеб оставался в соседнем зале. Между проверками других входов не было."]},{"id":"case-02","title":"Следы у павильона","question":"У павильона нашли следы, похожие на подошвы смотрителя. Какой вывод подтверждается уликами?","options":["Смотритель проник в павильон ночью","Человек со следами украл экспонат","Следы оставлены именно ботинками смотрителя","Кто-то прошёл к двери после 22:00"],"answer":3,"explanation":"После 22:00 на нетронутом снегу появился путь к двери. Это подтверждает проход человека после указанного времени. Распространённый рисунок подошвы не устанавливает личность, а следы у входа не доказывают ни вход внутрь, ни кражу.","difficulty":"Лёгкая","category":"Оценка улик","clues":["В 22:00 снегопад закончился; дежурный сфотографировал полностью нетронутую дорожку.","В 23:00 на дорожке появились человеческие следы, ведущие к двери и обратно.","В этот час не было нового снега, ветра или оттепели.","Рисунок подошвы совпадает с ботинками смотрителя, но такая модель продаётся массово."]},{"id":"case-03","title":"Лишний удар колокола","question":"После пропажи макета опросили сотрудников театра. Какое показание противоречит установленному порядку событий?","options":["«Я услышал колокол после выключения основного света»","«Когда звучал колокол, основной свет ещё горел»","«Я вышел через две минуты после колокола, при основном свете»","«Я вошёл после выключения основного света»"],"answer":0,"explanation":"Единственный сигнал прозвучал в 19:00, а основной свет отключили в 19:05. Поэтому услышать именно этот сигнал после отключения было невозможно. Противоречивое показание требует уточнения, но само по себе не доказывает причастность к пропаже.","difficulty":"Лёгкая","category":"Проверка показаний","clues":["Запись диспетчера подтверждает: колокол прозвучал ровно один раз, в 19:00.","Основной свет горел непрерывно до 19:05, после чего его выключили до закрытия театра.","Все свидетели говорят об этом вечере, этом колоколе и основном свете; других сигналов или записей не было."]},{"id":"case-04","title":"Одно правдивое показание","question":"В учебной реконструкции один из трёх участников спрятал папку. Из трёх высказываний истинно ровно одно. Кто спрятал папку?","options":["Артём","Борис","Вера","Установить невозможно"],"answer":2,"explanation":"Если папку спрятала Вера, только слова Артёма истинны: он не прятал папку. Слова Бориса и Веры ложны. При Артёме правдивы Борис и Вера, при Борисе — Артём и Вера. Только вариант с Верой даёт ровно одно истинное высказывание.","difficulty":"Средняя","category":"Логика показаний","clues":["Папку спрятал ровно один человек из трёх: Артём, Борис или Вера.","Артём: «Я папку не прятал».","Борис: «Папку спрятал Артём».","Вера: «Я папку не прятала».","По условиям реконструкции ровно одно из этих высказываний истинно."]},{"id":"case-05","title":"Письмо из кабинета","question":"Илья предъявил письмо, отправленное с его рабочего компьютера во время исчезновения образца. Что это письмо доказывает?","options":["Илья всё время находился у компьютера","С компьютера было отправлено письмо, но присутствие Ильи не установлено","Илья заранее подготовил ложное алиби","Письмо отправил другой сотрудник"],"answer":1,"explanation":"Запись подтверждает отправку с конкретного компьютера. Поскольку доступны отложенная отправка и удалённое управление, она не устанавливает физическое присутствие Ильи. Нельзя также заключить, что он намеренно создал ложное алиби или что письмо отправил другой человек.","difficulty":"Средняя","category":"Цифровые следы","clues":["Образец исчез между 14:00 и 14:10.","Почтовый журнал достоверно фиксирует отправку письма с компьютера Ильи в 14:05.","На компьютере доступны отложенная отправка и удалённое управление.","Записей присутствия людей в кабинете за этот период нет."]},{"id":"case-06","title":"Порванная пломба","question":"Коробку передавали между хранителями. В каком промежутке, исходя только из проверок, повредили пломбу?","options":["После проверки в 14:20 и не позднее проверки в 15:00","Только между 14:20 и 14:45","Только между 14:45 и 15:00","До 14:20"],"answer":0,"explanation":"Последнее подтверждение целой пломбы относится к 14:20, первое подтверждение повреждения — к 15:00. При передаче в 14:45 пломбу не осмотрели, поэтому нельзя сузить промежуток до времени одного хранителя.","difficulty":"Лёгкая","category":"Временная линия","clues":["В 14:20 Анна передала коробку Борису; оба проверили и записали, что пломба цела.","В 14:45 Борис передал коробку Вере, не проверяя пломбу.","В 15:00 Вера и заведующий впервые зафиксировали порванную пломбу.","После повреждения пломбу не заменяли и не восстанавливали."]},{"id":"case-07","title":"Билет с контрольной цифрой","question":"В архиве нашли четыре номера билетов. Какой номер проходит описанную проверку?","options":["3174","4320","2569","3414"],"answer":3,"explanation":"Для номера 3414 сумма равна 3 + 2 × 4 + 3 × 1 = 14, её последняя цифра — 4. Для остальных номеров расчёт даёт соответственно 6, 6 и 0, которые не совпадают с последними цифрами билетов. Прохождение проверки не доказывает подлинность билета целиком.","difficulty":"Средняя","category":"Проверка документов","clues":["Номер состоит из трёх основных цифр и четвёртой, контрольной.","Чтобы получить контрольную цифру, складывают первую цифру, удвоенную вторую и утроенную третью.","Контрольная цифра — последняя цифра получившейся суммы."]},{"id":"case-08","title":"Четыре шкафчика","question":"Следователь восстанавливает расположение предметов до перестановки. В каком шкафчике лежала папка?","options":["В первом","В третьем","Во втором","В четвёртом"],"answer":2,"explanation":"Четвёртый шкафчик занят блокнотом. Среди первых трёх фонарь должен стоять левее папки, а ключ — правее. Единственный порядок: фонарь, папка, ключ. Поэтому папка лежала во втором шкафчике.","difficulty":"Средняя","category":"Пространственная логика","clues":["Четыре шкафчика пронумерованы слева направо от 1 до 4.","В них лежали папка, ключ, фонарь и блокнот — по одному предмету в каждом.","Блокнот лежал в четвёртом шкафчике.","Фонарь лежал левее папки, а ключ — правее папки."]},{"id":"case-09","title":"Слишком быстрый переход","question":"Какое показание невозможно согласовать с проверенными временем и маршрутом?","options":["«В 18:10 я уже был в восточном корпусе»","«В восточный корпус я попал не раньше 18:15»","«В 18:10 я ещё мог быть на переходе»","«После 18:03 я некоторое время оставался в западном корпусе»"],"answer":0,"explanation":"После зафиксированного присутствия в западном корпусе в 18:03 человек мог попасть в восточный не раньше 18:15. Заявление о 18:10 противоречит минимальному времени пути. Остальные показания допускают согласованную последовательность событий.","difficulty":"Лёгкая","category":"Проверка алиби","clues":["В 18:03 камера с точными часами сняла свидетеля внутри западного корпуса.","Единственный открытый путь в восточный корпус занимает не менее 12 минут, включая время от камеры до выхода.","Транспорт, короткие проходы и другие входы исключены условиями дела."]},{"id":"case-10","title":"Часы в мастерской","question":"В какой момент по точному времени снимок зафиксировал открытый ящик?","options":["В 16:42","В 16:30","В 16:36","В 16:24"],"answer":1,"explanation":"Камерные часы спешат на шесть минут, поэтому из показания 16:36 нужно вычесть шесть минут: получится 16:30. Дополнительная запись настенных часов согласуется с тем же моментом: 16:26 плюс четыре минуты.","difficulty":"Средняя","category":"Временная линия","clues":["На снимке открытого ящика отметка времени камеры — 16:36.","Проверка до и после события показала: часы камеры постоянно спешат на 6 минут.","В том же кадре настенные часы показывают 16:26; они постоянно отстают на 4 минуты."]},{"id":"case-11","title":"Карта у считывателя","question":"Дверь открыли картой Ольги. Какой следующий шаг лучше всего поможет установить, кто вошёл?","options":["Считать владельца карты вошедшим без дополнительных проверок","Проверить только должность Ольги","Исключить Ольгу, потому что картой мог воспользоваться другой","Сопоставить время прохода с записью камеры у этой двери"],"answer":3,"explanation":"Журнал связывает проход с картой, а не непосредственно с человеком. Запись камеры в тот же момент может показать вошедшего и проверить связь между картой и владельцем. Возможность передачи карты не доказывает ни участие Ольги, ни её непричастность.","difficulty":"Средняя","category":"Выбор проверки","clues":["Журнал фиксирует открытие двери картой Ольги в 21:14.","Карты не используют биометрическую проверку и могут передаваться другим людям.","Камера у двери работала; её время синхронизировано с журналом.","Запись камеры ещё не просмотрена."]},{"id":"case-12","title":"Три закрытых сейфа","question":"Ключ спрятан в одном из трёх сейфов. Ровно две надписи истинны. Какой сейф нужно открыть?","options":["Первый","Третий","Второй","Любой: сведений недостаточно"],"answer":2,"explanation":"Если ключ во втором сейфе, первая надпись ложна, вторая и третья истинны — ровно две. При ключе в первом все три надписи ложны. При ключе в третьем истинна только первая. Подходит только второй сейф.","difficulty":"Сложная","category":"Логика показаний","clues":["Ключ лежит ровно в одном сейфе; других мест нет.","На первом сейфе: «Ключ в третьем сейфе».","На втором: «Ключ не в первом и не в третьем сейфе».","На третьем: «Ключ во втором сейфе».","Из этих трёх надписей ровно две истинны."]},{"id":"case-13","title":"Два рассказа об одном шуме","question":"Два сотрудника одинаково описали звук разбитого стекла. Насколько это усиливает версию о разбитом окне?","options":["Это два независимых подтверждения разбитого окна","Рассказ второго не является независимым подтверждением звука","Совпадение рассказов доказывает сговор","Разбитого окна точно не было"],"answer":1,"explanation":"Второй сотрудник пересказывает слова первого и сам звука не слышал. Поэтому у версии один первоначальный источник, а не два независимых наблюдения. Это не доказывает ни ошибочность первого рассказа, ни сговор; полезно осмотреть окно и найти другие данные.","difficulty":"Средняя","category":"Надёжность свидетельств","clues":["Первый сотрудник говорит, что лично услышал звон стекла за стеной.","Второй повторяет те же детали.","При уточнении второй признаёт: он был в наушниках, ничего не слышал и узнал о звуке от первого.","Окно пока не осмотрено."]},{"id":"case-14","title":"Переставленные таблички","question":"Три ящика подписаны неверно. Из ящика «Смешанный» достали медный жетон. Что находится в ящике с надписью «Медные»?","options":["Только медные жетоны","Смесь медных и серебряных жетонов; количество неизвестно","По одному жетону каждого вида","Только серебряные жетоны"],"answer":3,"explanation":"Ящик «Смешанный» не может быть смешанным, а найденный медный жетон означает, что в нём только медные. Ящик «Серебряные» не может содержать только серебряные и уже не может быть медным, поэтому он смешанный. Следовательно, в ящике «Медные» находятся только серебряные жетоны.","difficulty":"Сложная","category":"Логика исключения","clues":["В одном ящике только медные жетоны, во втором — только серебряные, в третьем — смесь обоих видов.","На ящиках надписи «Медные», «Серебряные» и «Смешанный».","Все три надписи неверны.","Из ящика с надписью «Смешанный» извлекли один медный жетон."]},{"id":"case-15","title":"Лифт между этажами","question":"После пропажи папки проверили рассказ курьера. Какое утверждение точно несовместимо с журналом лифта?","options":["«Я поднялся этим лифтом с первого на четвёртый этаж в 12:06»","«В 12:03 я вышел из этого лифта на втором этаже»","«На четвёртый этаж я мог подняться по лестнице»","«В 12:08 я мог находиться на первом этаже»"],"answer":0,"explanation":"С 12:04 до 12:10 лифт был заблокирован на втором этаже, поэтому поездка в 12:06 невозможна. Прибытие на второй этаж в 12:03 согласуется с журналом, а перемещение по доступной лестнице журнал лифта не опровергает.","difficulty":"Лёгкая","category":"Проверка показаний","clues":["В здании один лифт и открытая лестница между всеми этажами.","Журнал точно фиксирует прибытие лифта с первого на второй этаж в 12:03.","С 12:04 по 12:10 лифт стоял на втором этаже с блокировкой движения.","Журнал исправен и фиксирует каждую поездку."]},{"id":"case-16","title":"Папки и дежурные","question":"Три дежурных сдавали разные папки в разное время. Кто сдал зелёную папку?","options":["Борис","Вера","Анна","Данных недостаточно"],"answer":2,"explanation":"Красная папка сдана в 10:00. Анна была раньше синей папки, но сама не сдавала красную, значит, Анна пришла в 10:10, а синюю папку сдали в 10:20. Анне остаётся зелёная. Борис не синий, поэтому он сдал красную в 10:00, Вера — синюю в 10:20.","difficulty":"Сложная","category":"Сопоставление фактов","clues":["Анна, Борис и Вера сдали по одной папке: красной, зелёной или синей.","Сдачи произошли в 10:00, 10:10 и 10:20 — по одному человеку в каждый момент.","Красную папку сдали первой.","Анна пришла раньше того, кто сдал синюю папку, и не сдавала красную.","Борис не сдавал синюю папку."]},{"id":"case-17","title":"Разрыв в записи","question":"Камера не записала четыре минуты у склада. Какой вывод из имеющихся данных наиболее обоснован?","options":["Камеру намеренно отключили ради кражи","Во время пропуска никто не входил","Виновен человек, отвечающий за камеры","Запись не показывает, что происходило в эти четыре минуты"],"answer":3,"explanation":"Отсутствие записи ограничивает наблюдение. Без диагностики нельзя установить причину сбоя, а без других источников — наличие проходов или чью-либо вину. Следующий полезный шаг — проверить технический журнал и независимые сведения за тот же промежуток.","difficulty":"Средняя","category":"Оценка улик","clues":["Видеофайл обрывается в 20:11 и возобновляется в 20:15.","Причина пропуска пока не установлена.","Датчика двери нет, показаний очевидцев за этот промежуток пока не получено."]},{"id":"case-18","title":"Последовательность печатей","question":"Четыре печати ставили по одной, без одновременных действий. В каком порядке их поставили?","options":["Круг, звезда, квадрат, треугольник","Звезда, круг, квадрат, треугольник","Круг, квадрат, звезда, треугольник","Круг, звезда, треугольник, квадрат"],"answer":0,"explanation":"Круг поставлен раньше звезды, звезда раньше квадрата, а квадрат раньше треугольника. Эти три связи образуют полную цепочку и оставляют только один порядок: круг, звезда, квадрат, треугольник.","difficulty":"Средняя","category":"Порядок событий","clues":["На пропуске стоят четыре печати: круг, звезда, квадрат и треугольник; каждую поставили один раз.","По подтверждённому журналу круг поставили раньше звезды.","Квадрат поставили после звезды, но до треугольника.","Все четыре действия выполнены последовательно."]},{"id":"case-19","title":"Две смены охраны","question":"Подмену сделали во время одной из двух смен. Камеры дают неполную картину. Какой вывод следует из условий?","options":["Подмена точно произошла в первую смену","Подмену сделали оба сотрудника вместе","Подмена произошла во вторую смену, но исполнитель не установлен","Виновен дежурный второй смены"],"answer":2,"explanation":"В конце первой смены независимо подтверждено наличие подлинного предмета, а к концу второй обнаружена копия. Значит, подмена произошла во вторую смену. В это время могли входить и дежурный, и реставратор, поэтому определить исполнителя по этим данным нельзя.","difficulty":"Сложная","category":"Границы вывода","clues":["Первая смена длилась с 08:00 до 12:00, вторая — с 12:00 до 16:00.","В 12:00 эксперт лично подтвердил подлинность предмета по скрытой метке.","В 16:00 эксперт обнаружил копию без этой метки.","С 12:00 до 16:00 доступ имели дежурный и реставратор; их перемещения записаны не полностью.","Предмет подменили один раз между 08:00 и 16:00. Проверки эксперта достоверны."]},{"id":"case-20","title":"След на запечатанном листе","question":"На внутреннем листе обнаружили отпечаток Саши. Какова доказательная сила этой находки?","options":["Саша вскрыл конверт после опечатывания","Саша касался листа, но отпечаток не устанавливает время касания","Саша точно не касался листа после опечатывания","Отпечаток доказывает, что Саша унёс конверт"],"answer":1,"explanation":"Совпадение устанавливает касание листа, но определить по отпечатку время не удалось. У Саши был законный доступ до опечатывания, поэтому находка не доказывает последующее вскрытие. Она также не исключает более позднее касание и ничего не говорит о переносе конверта.","difficulty":"Сложная","category":"Границы вывода","clues":["Эксперт достоверно сопоставил отпечаток на листе с отпечатком Саши.","Время появления отпечатка определить не удалось.","Саша законно проверял этот лист за час до его помещения в конверт.","Расследуется предполагаемое вскрытие конверта после опечатывания."]}];
const EMOTIONAL_SCENARIOS=[{"id":"eq-01","title":"Резкое замечание","question":"На встрече коллега сказал: «Твой расчёт никуда не годится». Ты чувствуешь злость, но хочешь понять ошибку и сохранить рабочий разговор. Что лучше сказать?","options":["«Возможно, расчёт плохой. Я переделаю его целиком»","«Вернёмся к этому, когда ты будешь настроен дружелюбнее»","«Я готов обсудить ошибки. Покажи конкретный пункт, и давай без общих оценок»","«Пришли все замечания письменно, сейчас обсуждать не будем»"],"answer":2,"explanation":"Этот ответ одновременно открывает путь к проверке расчёта и обозначает границу допустимого тона. Он не требует соглашаться с общей оценкой. Пауза или письменные замечания тоже могут помочь, если разговор продолжит накаляться, но сейчас можно попробовать конкретный вопрос.","difficulty":"Лёгкая","category":"Ответ на критику"},{"id":"eq-02","title":"Сообщение без ответа","question":"Друг прочитал твоё сообщение два часа назад и не ответил. Ты замечаешь мысль: «Я ему больше не нужен». Друг раньше иногда отвечал вечером. Какой первый шаг полезнее?","options":["Отделить факт отсутствия ответа от догадки об отношениях и вернуться к своим делам до вечера","Сразу спросить, почему он стал отдаляться","Удалить сообщение, чтобы не думать о нём","Попросить общего знакомого выяснить причину молчания"],"answer":0,"explanation":"Известно только, что ответа пока нет. Привычка друга отвечать вечером даёт альтернативное объяснение и позволяет не действовать из тревожной догадки. Если молчание станет повторяющимся и важным для отношений, ожидания можно обсудить напрямую.","difficulty":"Лёгкая","category":"Эмоции и интерпретации"},{"id":"eq-03","title":"Незаметный вклад","question":"На общем собрании руководитель похвалил проект, но назвал только коллегу, хотя вы работали вдвоём. Ты чувствуешь обиду. С чего лучше начать?","options":["На следующем собрании подробно перечислить все ошибки коллеги","Решить, что руководитель намеренно присвоил твой вклад другому","Перестать помогать коллеге, пока твой вклад не заметят","Лично уточнить у руководителя ситуацию, назвать свой вклад и договориться, как отражать участие дальше"],"answer":3,"explanation":"Личный разговор с конкретными фактами помогает защитить признание своего вклада и проверить, было ли упоминание случайным пропуском. Он не требует подавлять обиду или заранее приписывать злой умысел. При повторении ситуации может понадобиться более формальная фиксация ответственности.","difficulty":"Средняя","category":"Самоуважение"},{"id":"eq-04","title":"Встреча снова отменена","question":"Друг в третий раз отменил встречу в последний момент. Он пишет, что перегружен. Ты сочувствуешь, но уже потерял время и деньги на дорогу. Как ответить?","options":["«Понимаю, ничего страшного», хотя внутри растёт раздражение","«Похоже, тебе сейчас тяжело. Мне тоже неудобны отмены в последний момент. Давай договоримся о подтверждении заранее»","«Давай больше не назначать встречи, пока ты не разберёшься со всем»","«Я приеду всё равно, тебе наверняка станет лучше от компании»"],"answer":1,"explanation":"Можно признать перегрузку друга и одновременно сказать о последствиях для себя. Конкретная договорённость делает границу понятной. Если отмены продолжатся, дистанция или другой формат встреч могут быть разумны, но сначала полезно обсудить рабочий вариант.","difficulty":"Лёгкая","category":"Личные границы"},{"id":"eq-05","title":"Перед выступлением","question":"За пять минут до короткого выступления ты чувствуешь напряжение и замечаешь мысль: «Если буду волноваться, всё испорчу». Материал подготовлен. Что сейчас полезнее?","options":["Срочно переписать выступление, чтобы оно стало безупречным","Попытаться полностью избавиться от волнения до выхода","Признать волнение, спокойно выдохнуть и сосредоточиться на первой фразе и главной мысли","Попросить аудиторию заранее не задавать вопросов"],"answer":2,"explanation":"Волнение не обязательно мешает говорить ясно. Признание состояния и небольшой выполнимый шаг возвращают внимание к задаче. Полная перестройка материала в последний момент может усилить нагрузку; цель сейчас — начать достаточно хорошо, а не добиться полного отсутствия эмоций.","difficulty":"Лёгкая","category":"Саморегуляция"},{"id":"eq-06","title":"Успех другого","question":"Коллега получил повышение, о котором ты тоже мечтал. Ты рад за него и одновременно завидуешь. Как лучше обойтись с этой смесью чувств?","options":["Убедить себя, что завидовать нельзя, и перестать об этом думать","Подробно сравнить ваши слабости, чтобы восстановить справедливость","Сразу попросить коллегу объяснить, почему выбрали именно его","Признать обе эмоции, поздравить настолько искренне, насколько получается, и отдельно выяснить свои шаги к росту"],"answer":3,"explanation":"Радость за другого и зависть могут сосуществовать. Зависть подсказывает, что собственное продвижение важно, но не требует обесценивать коллегу. Разговор о критериях роста лучше вести с тем, кто принимает решения, когда появится готовность обсуждать конкретные действия.","difficulty":"Средняя","category":"Сложные эмоции"},{"id":"eq-07","title":"Непрошеные решения","question":"Близкий человек рассказывает о тяжёлом дне. Ты уже придумал несколько решений, но он пока продолжает говорить. Что лучше сделать?","options":["Выслушать и уточнить: «Тебе сейчас важнее, чтобы я побыл рядом, или вместе поискать решение?»","Сразу перечислить решения, чтобы не затягивать переживание","Рассказать похожую историю о себе, чтобы показать понимание","Уверить его, что завтра всё наверняка наладится"],"answer":0,"explanation":"Уточнение помогает согласовать поддержку с потребностью человека. Иногда полезно быть услышанным, иногда — получить помощь с действиями. Советы и личные истории могут пригодиться позже, если собеседник их хочет; обещать благополучный исход без оснований не нужно.","difficulty":"Лёгкая","category":"Эмпатия"},{"id":"eq-08","title":"Пауза в споре","question":"Во время спора с партнёром ты начал перебивать и повышать голос. Вопрос важен, но срочного решения не требует. Как взять паузу, сохранив контакт?","options":["Молча уйти и дождаться, пока партнёр сам начнёт разговор","Сказать: «Я сейчас слишком злюсь и говорю резко. Мне нужно двадцать минут; затем вернёмся к разговору»","Продолжать обсуждение, пока вопрос не будет окончательно закрыт","Попросить партнёра сначала признать свою неправоту, а потом сделать паузу"],"answer":1,"explanation":"Названная причина и конкретное время возвращения отличают паузу для восстановления от наказания молчанием. После паузы важно действительно вернуться или согласовать новое время. Такой ответ также признаёт ответственность за собственный тон.","difficulty":"Средняя","category":"Конфликт"},{"id":"eq-09","title":"Сложная обратная связь","question":"Сотрудник дважды сдал отчёт без проверки чисел. Это задержало команду. Ты отвечаешь за результат. Как начать разговор, чтобы помочь исправить работу?","options":["«Ты невнимательный человек, и команда это замечает»","«Ничего страшного, я снова всё проверю сам»","«Пожалуйста, просто будь внимательнее»","«В двух последних отчётах были ошибки в итогах, и проверка задержала сдачу. Давай разберём причину и согласуем проверку перед отправкой»"],"answer":3,"explanation":"Ответ опирается на наблюдаемое поведение, объясняет последствия и приглашает найти причину. Договорённость о проверке даёт понятное ожидание. Ярлык о личности редко помогает исправлению, а полное принятие работы на себя скрывает проблему.","difficulty":"Средняя","category":"Обратная связь"},{"id":"eq-10","title":"Последняя просьба вечером","question":"Коллега просит вечером помочь с несрочной задачей. Ты уже договорился о семейном времени и чувствуешь вину при мысли об отказе. Как ответить?","options":["Согласиться и надеяться, что семья поймёт без объяснений","Не отвечать до утра, чтобы избежать неловкости","«Сегодня вечером я занят. Могу посмотреть завтра в десять; если раньше, понадобится другой вариант»","Подробно оправдаться и попросить коллегу решить, достаточно ли важна твоя причина"],"answer":2,"explanation":"Ясный отказ на конкретное время вместе с реальной альтернативой уважает и свои обязательства, и потребность коллеги. Чувство вины может сохраняться даже при обоснованной границе. Для отказа от несрочной просьбы не требуется передавать другому право оценивать личные планы.","difficulty":"Лёгкая","category":"Личные границы"},{"id":"eq-11","title":"Неудачная шутка","question":"Ты пошутил о привычке друга при других людях. Позже он сказал, что ему было унизительно. Ты не хотел обидеть. Как лучше ответить?","options":["«Мне жаль, что ты так воспринял, ведь я не хотел ничего плохого»","«Я сделал твою привычку поводом для смеха при других. Понимаю, что это задело. Прости; больше не буду так шутить»","«Я объясню всем, что на самом деле ты не такой»","«Давай забудем, чтобы не делать ситуацию ещё неприятнее»"],"answer":1,"explanation":"Ответ признаёт конкретное действие и его влияние, не споря с переживанием друга. Намерение объясняет контекст, но не отменяет причинённую неловкость. Публичное исправление стоит согласовать с другом: незапрошенное обсуждение может снова поставить его в неудобное положение.","difficulty":"Средняя","category":"Ответственность"},{"id":"eq-12","title":"Тихий участник","question":"Обычно активная участница встречи сегодня молчит. Ты ведёшь обсуждение. Как поддержать участие, не делая выводов о её состоянии?","options":["Предложить всей группе время подумать и возможность добавить мнение устно или письменно; при необходимости уточнить у неё наедине","Публично спросить, почему она обиделась","Назначить ей выступление следующей, чтобы помочь включиться","Считать молчание согласием со всеми решениями"],"answer":0,"explanation":"Молчание может иметь разные причины. Выбор способа участия уменьшает давление и не навязывает объяснение. Личный нейтральный вопрос уместен, если есть повод проверить, нужна ли поддержка; согласие с решениями лучше подтверждать отдельно.","difficulty":"Средняя","category":"Внимание к другим"},{"id":"eq-13","title":"Раздражение на мелочи","question":"После нескольких напряжённых дней тебя раздражают обычные вопросы семьи. Ты замечаешь усталость и начинаешь отвечать резко. Что полезнее сделать сейчас?","options":["Объяснить семье, что им следует самим догадаться о твоей усталости","Запретить себе раздражаться и продолжить дела в прежнем темпе","Назвать усталость, извиниться за резкость и попросить короткое время для отдыха с понятным возвращением к общению","Начать подробный разговор обо всех накопившихся семейных проблемах"],"answer":2,"explanation":"Усталость может объяснять повышенную раздражительность, но не снимает ответственности за тон. Короткая обозначенная пауза и восстановление контакта помогают не переносить перегрузку на близких. Более широкие вопросы стоит обсуждать, когда для этого появятся силы.","difficulty":"Лёгкая","category":"Саморегуляция"},{"id":"eq-14","title":"Несогласие с руководителем","question":"Руководитель при всех предлагает срок, который по твоим расчётам нереалистичен. Он заметно торопится. Молчание будет воспринято как согласие. Как ответить?","options":["Согласиться сейчас, а предупредить о задержке ближе к сроку","Кратко обозначить риск, назвать ограничение и предложить выбор между меньшим объёмом и более поздней датой","Подробно перечислить все прошлые ошибки планирования руководителя","Сказать, что команда сделает максимум, не уточняя обязательств"],"answer":1,"explanation":"Краткое несогласие с фактами и вариантами позволяет учесть спешку руководителя, сохранив ясность обязательств. Оно не гарантирует удобного ответа, но делает риск видимым до принятия решения. Прошлые ошибки и расплывчатое обещание отвлекают от текущего выбора.","difficulty":"Сложная","category":"Уверенное общение"},{"id":"eq-15","title":"Чужая потеря","question":"Знакомая рассказала, что умер её близкий человек. Вы не очень близки, но ты хочешь поддержать её без навязчивости. Какой ответ уместнее?","options":["«Ты сильная, скоро обязательно станет легче»","«Я точно знаю, что ты чувствуешь»","«Попробуй отвлечься и не думать об этом постоянно»","«Мне очень жаль. Если захочешь, я могу послушать или помочь с конкретным делом; отвечать сейчас не нужно»"],"answer":3,"explanation":"Простое сочувствие и ненавязчивая помощь оставляют человеку выбор. Не нужно утверждать, что знаешь его переживание, или задавать срок восстановления. Предложение конкретного посильного дела может быть полезнее общего требования «держаться».","difficulty":"Сложная","category":"Бережная поддержка"},{"id":"eq-16","title":"Ошибка в общем письме","question":"Ты обнаружил свою ошибку в уже отправленном общем письме. Она влияет на план команды, но её ещё можно исправить. Ты чувствуешь стыд и хочешь сначала понять, кто уже заметил. Что лучше сделать?","options":["Быстро сообщить об ошибке, дать исправленные данные и обозначить, что нужно пересмотреть","Подождать вопроса, чтобы не привлекать лишнего внимания","Отправить новые данные без пояснения, что предыдущие были неверны","Начать с длинного объяснения обстоятельств, из-за которых ты ошибся"],"answer":0,"explanation":"Своевременное ясное исправление уменьшает последствия и возвращает команде возможность действовать. Признание ошибки не требует публичного самоунижения. Причины можно разобрать позже, если это поможет предотвратить повторение; сейчас важнее исправленные данные и затронутые решения.","difficulty":"Средняя","category":"Ответственность"},{"id":"eq-17","title":"Просьба сохранить секрет","question":"Коллега рассказал, что ищет другую работу, и попросил не обсуждать это с командой. Другой сотрудник замечает его отсутствие и просит тебя объяснить причину. У тебя нет обязанности раскрывать личные планы коллеги. Что ответить?","options":["«Он пока не хочет говорить, но скоро всё станет понятно»","«Я не буду обсуждать его личные обстоятельства. По рабочим вопросам лучше спросить его напрямую»","Выдумать бытовую причину отсутствия, чтобы защитить секрет","Поделиться информацией, попросив никому её не передавать"],"answer":1,"explanation":"Прямая граница защищает доверие, не раскрывая секрет намёком и не создавая ложной истории. Рабочие вопросы можно адресовать самому коллеге. Здесь по условиям нет обязанности сообщать его личные планы; другие обязанности потребовали бы отдельной оценки.","difficulty":"Сложная","category":"Доверие"},{"id":"eq-18","title":"Две потребности в споре","question":"Вы с соседом по квартире спорите о гостях. Тебе нужна тишина перед ранней сменой, ему важно видеть друзей дома. Гости ещё не приглашены. Какой ход лучше помогает найти решение?","options":["Договориться, что побеждает тот, кто первым заявил о планах","Предложить обоим полностью отказаться от гостей на месяц","Уточнить важные дни и допустимое время шума, затем согласовать конкретные часы и предупреждение о гостях","Разрешить встречу сейчас, рассчитывая, что сосед позже сам уступит"],"answer":2,"explanation":"За позициями стоят понятные потребности: отдых и общение. Обсуждение времени, частоты и предупреждения позволяет искать совместимые условия. Решение не обязано быть симметричным в каждый отдельный день, но должно быть ясным и приемлемым для обоих.","difficulty":"Сложная","category":"Переговоры"},{"id":"eq-19","title":"Решение из обиды","question":"Твой проект отклонили. На пике обиды хочется немедленно выйти из команды, хотя раньше работа тебе подходила. Срочного ответа не требуется. Какой следующий шаг полезнее?","options":["Отложить необратимое решение до снижения накала, затем выяснить причины отказа и оценить дальнейшие варианты","Сразу уйти, чтобы доказать, что твоё мнение имеет вес","Пообещать остаться при любых условиях, чтобы не поддаться эмоциям","Написать команде все накопившиеся претензии одним сообщением"],"answer":0,"explanation":"Пауза оставляет свободу уйти или остаться после более полной оценки. Обиду полезно признать: она может указывать на важную потребность, но одного острого момента недостаточно для вывода обо всей работе. После паузы стоит проверить причины отказа и повторяемость проблемы.","difficulty":"Сложная","category":"Решения и эмоции"},{"id":"eq-20","title":"Разный темп примирения","question":"После ссоры ты извинился за резкие слова. Друг отвечает: «Спасибо, но мне пока нужно время». Как отреагировать?","options":["Попросить сразу сказать, простил ли он тебя, чтобы прекратить неопределённость","Повторять извинения сообщениями, пока он не ответит теплее","Решить, что он отверг извинение, и больше не выходить на связь","Принять просьбу о времени, подтвердить готовность поговорить позже и не требовать немедленного прощения"],"answer":3,"explanation":"Извинение — твоя ответственность, а готовность к примирению остаётся выбором другого человека. Уважение к паузе поддерживает смысл извинения. Время последующего контакта можно ненавязчиво согласовать, если друг готов, но его нельзя превращать в срок обязательного прощения.","difficulty":"Средняя","category":"Восстановление отношений"},{"id":"eq-21","title":"Чувство или требование","question":"Близкий человек говорит: «Мне тревожно, поэтому ты должен постоянно присылать своё местоположение». Ты готов обсудить тревогу, но постоянное отслеживание тебе не подходит. Как ответить?","options":["Согласиться, потому что отказ означает безразличие к его тревоге","«Понимаю, что тебе тревожно. Постоянно делиться местоположением я не готов. Давай обсудим, какая поддержка подойдёт нам обоим»","«Твоя тревога нелогична, поэтому обсуждать нечего»","Пообещать делиться местоположением, а затем незаметно отключить передачу"],"answer":1,"explanation":"Признание чужой эмоции не обязывает соглашаться с любым предложенным требованием. Ясная граница и поиск взаимоприемлемой поддержки сохраняют честность. Обесценивание тревоги и обещание, которое ты не намерен выполнять, мешают доверию.","difficulty":"Сложная","category":"Эмпатия и границы"},{"id":"eq-22","title":"Неясное сообщение","question":"Руководитель написал: «Завтра обсудим твой результат». Ты почувствовал страх и сразу решил, что тебя будут ругать. В сообщении больше ничего нет. Какой ответ лучше помогает работать с неопределённостью?","options":["Немедленно написать подробное оправдание за все возможные недочёты","Попросить коллег угадать настроение руководителя","Отметить, что тон и цель пока неизвестны, и нейтрально уточнить, какие материалы подготовить к обсуждению","Убедить себя, что сообщение точно означает похвалу"],"answer":2,"explanation":"Нейтральное уточнение даёт полезную информацию и помогает подготовиться. Страх реален как чувство, но не подтверждает негативную цель встречи. Заменять тревожную догадку уверенной позитивной тоже не нужно: пока данных недостаточно для обеих версий.","difficulty":"Средняя","category":"Эмоции и интерпретации"}];
// ── Mission editor and multi-attribute rewards ───────────────────────────
let draftAlloc=[];
function missionForm(id=null,preset=null){const m=id?state.missions.find(m=>m.id===id):preset;const active=state.attributes.filter(a=>!a.archived);draftAlloc=structuredClone(m?.allocations|| (active.length?[{id:active[0].id,weight:100}]:[]));Modal.open(id?'Редактировать миссию':'Новая миссия',`<form id="mission-form" novalidate><div class="form-grid"><label class="field span2">Название миссии<input name="title" placeholder="Что приблизит тебя к цели?" maxlength="160" required value="${esc(m?.title||'')}"></label><label class="field span2">Описание<textarea name="description" placeholder="Конкретный шаг и ожидаемый результат" maxlength="3000">${esc(m?.description||'')}</textarea></label><label class="field">Дата<input type="date" name="date" required value="${m?.date||selectedDate}"></label><label class="field">Начало<input type="time" name="time" value="${m?.time||''}"></label><label class="field">Длительность, мин<input name="duration" type="number" min="0" max="1440" value="${m?.duration||''}" placeholder="Необязательно"></label><label class="field">Сложность<select name="difficulty">${DIFFICULTIES.map((d,i)=>`<option value="${i}" ${i===(m?.difficulty??state.settings.defaultDifficulty)?'selected':''}>${d[0]} · ${d[1]} ОП</option>`).join('')}</select></label><label class="field">Повторение<select name="repeat">${[['none','Без повторения'],['daily','Каждый день'],['weekdays','По дням недели'],['weekly','Каждую неделю'],['interval','Свой интервал']].map(([v,t])=>`<option value="${v}" ${m?.repeat===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Приоритет<select name="priority">${['Обычный','Высокий','Критический'].map((t,i)=>`<option value="${i}" ${m?.priority===i?'selected':''}>${t}</option>`).join('')}</select></label><div class="span2" id="repeat-details"></div><label class="field">Категория<select name="category">${CATEGORIES.map(c=>`<option ${m?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">Своя награда, ОП<input name="customXP" type="number" min="0" max="10000" placeholder="Автоматически" value="${m?.customXP??''}"></label></div><hr class="divider"><div class="flex between"><h3>Распределение опыта</h3><button type="button" class="btn ghost" id="normalize">Уравнять до 100%</button></div><p class="field-hint" style="margin-top:6px">Одна миссия — несколько направлений развития.</p><div id="allocations"></div><button type="button" class="btn ghost" id="add-allocation">${icon('plus',15)}Добавить атрибут</button><div class="xp-preview space"><div class="flex between"><span class="muted small">Награда за выполнение</span><strong id="xp-value"></strong></div><p class="field-hint" style="margin-top:9px" id="xp-formula"></p><p class="small" id="allocation-total" style="margin-top:8px"></p></div><label class="field space">Заметки<textarea name="notes" maxlength="3000" placeholder="Личные пометки">${esc(m?.notes||'')}</textarea></label><div class="error" id="form-error" role="alert"></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Отмена</button><button class="btn primary" type="submit">${id?'Сохранить':'Создать миссию'}</button></div></form>`,true);
const f=$('#mission-form');const details=()=>{const repeat=f.elements.repeat.value;$('#repeat-details').innerHTML=repeat==='weekdays'?`<div class="weekdays">${['Вс','Пн','Вт','Ср','Чт','Пт','Сб'].map((d,i)=>`<label class="weekday"><input type="checkbox" name="weekday" value="${i}" ${(m?.weekdays||[1,2,3,4,5]).includes(i)?'checked':''}>${d}</label>`).join('')}</div>`:repeat==='interval'?`<label class="field">Повторять каждые, дней<input type="number" name="interval" min="1" max="365" value="${m?.interval||2}"></label>`:''};details();f.elements.repeat.onchange=details;
function allocRender(){const available=state.attributes.filter(a=>!a.archived||draftAlloc.some(x=>x.id===a.id));$('#allocations').innerHTML=draftAlloc.map((a,i)=>`<div class="alloc-row"><select aria-label="Атрибут ${i+1}" data-alloc-id="${i}">${available.map(s=>`<option value="${s.id}" ${s.id===a.id?'selected':''}>${esc(s.name)}${s.archived?' (в архиве)':''}</option>`).join('')}</select><input type="number" aria-label="Доля атрибута ${i+1}, процентов" min="0" max="100" step="1" value="${a.weight}" data-alloc-weight="${i}"><span id="alloc-xp-${i}"></span><button class="icon-btn" type="button" data-remove-alloc="${i}" aria-label="Убрать атрибут">${icon('close',14)}</button></div>`).join('')||'<p class="field-hint space">Сначала создай атрибут в разделе «Атрибуты».</p>';$$('[data-alloc-id]').forEach(s=>s.onchange=()=>{draftAlloc[+s.dataset.allocId].id=s.value;preview()});$$('[data-alloc-weight]').forEach(s=>s.oninput=()=>{draftAlloc[+s.dataset.allocWeight].weight=Number(s.value);preview()});$$('[data-remove-alloc]').forEach(b=>b.onclick=()=>{draftAlloc.splice(+b.dataset.removeAlloc,1);allocRender()});preview()}
function preview(){const custom=f.elements.customXP.value,duration=Number(f.elements.duration.value)||0,base=DIFFICULTIES[+f.elements.difficulty.value][1],xp=XPSystem.mission({customXP:custom,duration,difficulty:+f.elements.difficulty.value});$('#xp-value').textContent=number(xp)+' ОП';$('#xp-formula').textContent=custom!==''?'Установлена своя награда. Множитель не применяется.':`${base} × ${(1+Math.min(180,duration)/180).toFixed(2).replace('.',',')} за время × ${state.settings.xpMultiplier} множитель. Бонус за время — не более ×2.`;const sum=draftAlloc.reduce((n,a)=>n+a.weight,0);$('#allocation-total').textContent=`Всего распределено: ${sum}%${sum===100?' · Готово к выполнению':' · Нужно 100%'}`;$('#allocation-total').className='small '+(sum===100?'accent':'gold');const distribution=XPSystem.distribute(xp,draftAlloc);draftAlloc.forEach((a,i)=>{const el=$('#alloc-xp-'+i);if(el)el.textContent='+'+(distribution[i]?.xp||0)+' ОП'})}
$('#normalize').onclick=()=>{const sum=draftAlloc.reduce((n,a)=>n+Math.max(0,a.weight),0);let rest=100;draftAlloc.forEach((a,i)=>{a.weight=i===draftAlloc.length-1?rest:Math.floor(sum?Math.max(0,a.weight)/sum*100:100/draftAlloc.length);rest-=a.weight});allocRender()};$('#add-allocation').onclick=()=>{const a=active.find(a=>!draftAlloc.some(x=>x.id===a.id));if(!a)return toast('Все доступные атрибуты уже добавлены.');draftAlloc.push({id:a.id,weight:0});allocRender()};['difficulty','duration','customXP'].forEach(n=>f.elements[n].addEventListener('input',preview));allocRender();f.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(f)),error=$('#form-error');if(!data.title.trim())return error.textContent='Укажи название миссии.';if(!validDate(data.date))return error.textContent='Укажи корректную дату.';if(!draftAlloc.length||draftAlloc.some(a=>!Number.isFinite(a.weight)||a.weight<0)||draftAlloc.reduce((n,a)=>n+a.weight,0)!==100)return error.textContent='Доли атрибутов должны быть неотрицательными и в сумме давать 100%.';if(new Set(draftAlloc.map(a=>a.id)).size!==draftAlloc.length)return error.textContent='Каждый атрибут можно добавить только один раз.';if(!f.checkValidity())return error.textContent='Проверь значения: длительность от 0 до 1440 минут, награда от 0 до 10 000.';const weekdays=$$('input[name=weekday]:checked',f).map(c=>+c.value);if(data.repeat==='weekdays'&&!weekdays.length)return error.textContent='Выбери хотя бы один день недели.';const mission={id:id||uid(),title:data.title.trim(),description:data.description,date:data.date,time:data.time,duration:Number(data.duration)||0,difficulty:Number(data.difficulty),repeat:data.repeat,weekdays,interval:Number(data.interval)||1,category:data.category,priority:Number(data.priority),customXP:data.customXP===''?null:Number(data.customXP),notes:data.notes,allocations:structuredClone(draftAlloc),archived:m?.archived||false,createdAt:m?.createdAt||new Date().toISOString()};if(id)state.missions[state.missions.findIndex(m=>m.id===id)]=mission;else state.missions.push(mission);addActivity(id?'Обновлена миссия «'+mission.title+'»':'Новая миссия «'+mission.title+'»','mission');save();Modal.close();render();toast(id?'Миссия обновлена':'Миссия добавлена в расписание')};}
const MissionManager={complete(id,date){const m=state.missions.find(m=>m.id===id);if(!m||completion(id,date)||date>today()||!due(m,date))return;const xp=XPSystem.mission(m),allocations=XPSystem.distribute(xp,m.allocations);if(!allocations.length){toast('Добавь в миссию хотя бы один существующий атрибут.',true);return missionForm(id)}const prev=Object.fromEntries(state.attributes.map(a=>[a.id,a.level])),profileLevel=XPSystem.level(totalXP()).level;const c={id:uid(),missionId:id,date,time:new Date().toISOString(),title:m.title,xp,allocations,duration:m.duration,difficulty:m.difficulty};state.completions.push(c);state.skipped=state.skipped.filter(s=>s.missionId!==id||s.date!==date);addActivity('Выполнено: '+m.title,'completion',xp,{completionId:c.id});recalcAttributes();const ups=state.attributes.filter(a=>a.level>prev[a.id]);ups.forEach(a=>addActivity(`${a.name}: уровень ${a.level}`,'level',0,{completionId:c.id}));Achievements.check();save();render();beep();Modal.open('Миссия выполнена',`<div style="text-align:center;padding:15px 0"><span class="skill-icon" style="--c:var(--accent);margin:auto;width:55px;height:55px">${icon('check',30)}</span><h3 class="space">${esc(m.title)}</h3><div style="font-size:43px;color:var(--accent);margin:12px 0">+${number(xp)} <span style="font-size:17px">ОП</span></div><div class="stack" style="text-align:left;gap:12px">${allocations.map(x=>`<div class="flex between"><span>${esc(state.attributes.find(a=>a.id===x.id)?.name||'Архивный атрибут')}</span><span class="accent">+${x.xp} ОП</span></div>`).join('')}</div>${ups.map(a=>`<p class="gold space">${esc(a.name)} — новый уровень ${a.level}</p>`).join('')}${XPSystem.level(totalXP()).level>profileLevel?`<p class="gold space">${esc(rankFor())} — уровень ${XPSystem.level(totalXP()).level}</p>`:''}<div class="modal-actions"><button class="btn" data-action="undo-mission" data-id="${id}" data-date="${date}">Отменить выполнение</button><button class="btn primary" data-action="close-modal">Продолжить</button></div></div>`);},undo(id,date){const c=completion(id,date);if(!c)return;state.completions=state.completions.filter(x=>x.id!==c.id);state.activity=state.activity.filter(x=>x.completionId!==c.id);recalcAttributes();Achievements.reconcile();save();Modal.close();render();toast('Выполнение отменено. Опыт и время восстановлены.')},remove(id){const m=state.missions.find(m=>m.id===id);confirmAction('Удалить миссию?',`«${m.title}» исчезнет из расписания. Полученный опыт и история выполнений сохранятся.`,()=>{state.missions=state.missions.filter(m=>m.id!==id);state.skipped=state.skipped.filter(x=>x.missionId!==id);save();render();toast('Миссия удалена',false,()=>{state.missions.push(m);save();render()})})}};
function missionMenu(id,date){const m=state.missions.find(m=>m.id===id);Modal.open(m.title,`<div class="stack" style="gap:8px"><button class="btn" data-action="edit-mission" data-id="${id}">${icon('edit')}Редактировать</button><button class="btn" data-action="duplicate-mission" data-id="${id}">${icon('copy')}Создать копию</button><button class="btn" data-action="skip-mission" data-id="${id}" data-date="${date}" ${completion(id,date)?'disabled':''}>${state.skipped.some(s=>s.missionId===id&&s.date===date)?'Вернуть в план':'Пропустить это повторение'}</button><button class="btn" data-action="archive-mission" data-id="${id}">${m.archived?'Вернуть из архива':'Архивировать миссию'}</button><button class="btn danger" data-action="delete-mission" data-id="${id}">${icon('trash')}Удалить миссию</button></div>`)}
// ── Attribute management ────────────────────────────────────────────────
function attributeForm(id){const a=state.attributes.find(a=>a.id===id);Modal.open(a?'Изменить атрибут':'Новый атрибут',`<form id="attribute-form"><div class="form-grid"><label class="field span2">Название<input name="name" required maxlength="80" placeholder="Например, визуальное мышление" value="${esc(a?.name||'')}"></label><label class="field">Категория<select name="category">${CATEGORIES.map(c=>`<option ${a?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">Значок<select name="icon">${ATTRIBUTE_ICONS.map(([v,t])=>`<option value="${v}" ${a?.icon===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field span2">Акцентный цвет<input type="color" name="accent" value="${a?.accent||ACCENTS[state.attributes.length%6]}"></label></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Отмена</button><button class="btn primary">Сохранить атрибут</button></div></form>`);$('#attribute-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim();if(!name)return;const data={name,category:f.get('category'),icon:f.get('icon'),accent:f.get('accent')};if(a)Object.assign(a,data);else state.attributes.push({...newAttribute(data.name,data.category,data.icon,data.accent)});addActivity((a?'Обновлён':'Создан')+' атрибут «'+name+'»','attribute');save();Modal.close();render();toast('Атрибут сохранён')}}
function attributeDetail(id){const a=state.attributes.find(a=>a.id===id);if(!a)return;Modal.open(a.name,`<div class="flex between"><span class="pill">${esc(a.category)}${a.archived?' · В архиве':''}</span><span class="accent">Уровень ${a.level}</span></div><div class="space"><div class="flex between small"><span>${number(a.totalXP)} ОП за всё время</span><span>${a.currentXP} / ${a.xpRequiredForNextLevel} ОП</span></div><div class="bar" style="--c:${a.accent};--p:${a.currentXP/a.xpRequiredForNextLevel*100}%;margin-top:12px"><i></i></div></div><h3 class="space">История развития</h3>${renderActivity(a.history.slice().reverse().slice(0,30).map(h=>({...h,type:'completion'})),'Пока нет опыта. Свяжи этот атрибут с новой миссией.')}<div class="modal-actions wrap"><button class="btn" data-action="edit-attribute" data-id="${id}">Изменить</button><button class="btn" data-action="archive-attribute" data-id="${id}">${a.archived?'Восстановить':'В архив'}</button><button class="btn danger" data-action="delete-attribute" data-id="${id}" aria-label="Удалить атрибут">${icon('trash',16)}</button></div>`)}
function removeAttribute(id){const a=state.attributes.find(a=>a.id===id);confirmAction('Удалить атрибут?',`«${a.name}» будет удалён. Общий опыт профиля сохранится. В связанных миссиях доли оставшихся атрибутов будут приведены к 100%. Миссии без атрибутов потребуется отредактировать.`,()=>{state.attributes=state.attributes.filter(a=>a.id!==id);for(const m of [...state.missions,...state.routines.flatMap(r=>r.missions)]){m.allocations=m.allocations.filter(x=>x.id!==id);let sum=m.allocations.reduce((s,x)=>s+x.weight,0),left=100;m.allocations.forEach((x,i)=>{x.weight=i===m.allocations.length-1?left:Math.floor(sum?x.weight/sum*100:100/m.allocations.length);left-=x.weight})}save();render();toast('Атрибут удалён')})}
function renderAttributes(matrix=false){const items=state.attributes.filter(a=>(skillFilter==='archived'?a.archived:!a.archived)&&(skillFilter==='all'||skillFilter==='archived'||a.category===skillFilter)&&a.name.toLocaleLowerCase('ru').includes(query.toLocaleLowerCase('ru')));return intro(matrix?'Карта твоих возможностей':'Атрибуты','Качества, которые растут вместе с твоими действиями.',`<button class="btn primary" data-action="new-attribute">${icon('plus',16)}Новый атрибут</button>`)+`<div class="toolbar"><input class="input" id="attribute-search" aria-label="Поиск атрибута" placeholder="Найти атрибут…" value="${esc(query)}"><select id="skill-filter" aria-label="Категория атрибутов">${[['all','Все категории'],...CATEGORIES.map(c=>[c,c]),['archived','Архив']].map(([v,t])=>`<option value="${v}" ${skillFilter===v?'selected':''}>${t}</option>`).join('')}</select></div>${matrix?CATEGORIES.filter(c=>items.some(a=>a.category===c)).map(c=>`<section class="space"><div class="flex" style="margin-bottom:15px"><span class="skill-icon" style="--c:var(--accent)">${icon('skills')}</span><h2>${c}</h2><span class="pill">${items.filter(a=>a.category===c).length} навыков</span><div style="height:1px;background:var(--line);flex:1"></div></div><div class="cards">${items.filter(a=>a.category===c).map(skillCard).join('')}</div></section>`).join(''):`<div class="cards">${items.map(skillCard).join('')}</div>`}${!items.length?empty('Атрибуты не найдены','Измени фильтр или добавь новое направление.','new-attribute','Создать атрибут','skills'):''}`}
// ── Calendar, mission catalogue and daily scheduling ────────────────────
function renderToday(){const ms=missionsOn(selectedDate),done=ms.filter(m=>completion(m.id,selectedDate)).length,xp=periodXP(selectedDate,selectedDate);return intro('В фокусе — сегодня',fmtDate(selectedDate),newMissionButton())+`<div class="toolbar"><button class="btn" data-action="day-shift" data-value="-1" aria-label="Предыдущий день">←</button><input type="date" id="day-picker" aria-label="Выбрать день" value="${selectedDate}"><button class="btn" data-action="day-shift" data-value="1" aria-label="Следующий день">→</button><button class="btn ghost" data-action="day-today">Сегодня</button><span class="grow"></span><span class="pill">${done} / ${ms.length} миссий · ${ms.length?Math.round(done/ms.length*100):0}%</span><span class="pill">${xp} ОП</span></div><section class="panel">${ms.length?ms.slice().sort((a,b)=>(a.time||'99').localeCompare(b.time||'99')).map(m=>renderMission(m,selectedDate)).join(''):empty('День открыт для нового','Запланируй хотя бы один осмысленный шаг.')}<div class="panel-footer">Серия активности: ${streaks().current} дн. · Доступно ${ms.reduce((s,m)=>s+XPSystem.mission(m),0)} ОП</div></section>`}
let missionSort='date',missionSearch='';
function renderMissions(){const items=state.missions.filter(m=>(missionFilter==='archived'?m.archived:!m.archived)&&m.title.toLowerCase().includes(missionSearch.toLowerCase())&&(missionFilter==='completed'?state.completions.some(c=>c.missionId===m.id):missionFilter==='planned'?!completion(m.id,today()):true)).sort((a,b)=>missionSort==='xp'?XPSystem.mission(b)-XPSystem.mission(a):missionSort==='priority'?b.priority-a.priority:a.date.localeCompare(b.date)||(a.time||'99').localeCompare(b.time||'99'));return intro('Каждая миссия имеет значение','Планируй действия и превращай их в опыт.',`<div class="flex wrap"><button class="btn" data-action="library">${icon('book',16)}Библиотека</button>${newMissionButton()}</div>`)+`<div class="toolbar"><input class="input" id="mission-search" placeholder="Поиск миссий…" aria-label="Поиск миссий" value="${esc(missionSearch)}"><select id="mission-list-filter" aria-label="Фильтр миссий">${[['all','Все активные'],['planned','Не выполнены сегодня'],['completed','Есть выполнения'],['archived','Архив']].map(([v,t])=>`<option value="${v}" ${missionFilter===v?'selected':''}>${t}</option>`).join('')}</select><select id="mission-sort" aria-label="Сортировка миссий">${[['date','По дате'],['priority','По приоритету'],['xp','По награде']].map(([v,t])=>`<option value="${v}" ${missionSort===v?'selected':''}>${t}</option>`).join('')}</select><span class="pill">${items.length} миссий</span></div><section class="panel">${items.length?items.map(m=>renderMission(m,m.repeat==='none'?m.date:(due(m,today())?today():m.date))).join(''):empty('Пока нет миссий','Создай свою миссию или выбери готовую в библиотеке.')}</section>`}
function renderSchedule(){let start,end,title,dates=[];if(scheduleMode==='week'){start=addDays(weekStart(),calendarOffset*7);dates=Array.from({length:7},(_,i)=>addDays(start,i));title=`${fmtDate(start,true)} — ${fmtDate(dates[6],true)}`}else{const d=parseDate(today());d.setDate(1);d.setMonth(d.getMonth()+calendarOffset);start=localDate(d);title=d.toLocaleDateString('ru-RU',{month:'long',year:'numeric'});const first=weekStart(start);dates=Array.from({length:42},(_,i)=>addDays(first,i))}return intro('Ритм развития','Найди место для важного в каждой неделе.',newMissionButton())+`<div class="toolbar"><div class="flex"><button class="btn ${scheduleMode==='week'?'primary':''}" data-action="schedule-mode" data-value="week">Неделя</button><button class="btn ${scheduleMode==='calendar'?'primary':''}" data-action="schedule-mode" data-value="calendar">Календарь</button></div><span class="grow"></span><button class="icon-btn" data-action="calendar-shift" data-value="-1" aria-label="Предыдущий период">←</button><h3>${title}</h3><button class="icon-btn" data-action="calendar-shift" data-value="1" aria-label="Следующий период">→</button><button class="btn ghost" data-action="calendar-reset">Сегодня</button></div>${scheduleMode==='week'?`<div class="week-grid">${dates.map(date=>`<section class="week-day" ${date===today()?'style="border-color:#7daba3"':''}><h3>${parseDate(date).toLocaleDateString('ru-RU',{weekday:'short'})}<span class="dim"> · ${parseDate(date).getDate()}</span></h3>${missionsOn(date).map(m=>`<div class="week-mission"><button class="mission-title" style="font-size:12px" data-action="edit-mission" data-id="${m.id}">${completion(m.id,date)?'✓ ':''}${esc(m.title)}</button><div class="dim" style="font-size:11px;margin-top:6px">${m.time?fmtTime(m.time)+' · ':''}${XPSystem.mission(m)} ОП</div></div>`).join('')}<button class="btn ghost wide" data-action="new-mission-date" data-date="${date}">${icon('plus',14)}Миссия</button></section>`).join('')}</div>`:`<div class="calendar">${Array.from({length:7},(_,i)=>['Вс','Пн','Вт','Ср','Чт','Пт','Сб'][(Number(state.settings.startOfWeek)+i)%7]).map(d=>`<div class="cal-head">${d}</div>`).join('')}${dates.map(date=>`<div class="cal-cell ${date.slice(0,7)!==start.slice(0,7)?'other':''} ${date===today()?'today':''}" data-action="calendar-day" data-date="${date}" tabindex="0" role="button" aria-label="${fmtDate(date)}: ${missionsOn(date).length} миссий"><div class="cal-day">${parseDate(date).getDate()}</div>${missionsOn(date).slice(0,3).map(m=>`<span class="cal-mission">${completion(m.id,date)?'✓ ':''}${esc(m.title)}</span>`).join('')}${missionsOn(date).length>3?`<small class="dim">+${missionsOn(date).length-3}</small>`:''}</div>`).join('')}</div><p class="field-hint space">Выбери день, чтобы открыть его миссии.</p>`}`}
// ── Presets and reusable routines ───────────────────────────────────────
const PRESETS=[['Изучение языка','Языки',30,2,[['Румынский язык',70],['Память',15],['Дисциплина',15]],'Разбери одну тему и составь пять собственных предложений.'],['Повторение слов','Языки',15,1,[['Румынский язык',60],['Память',40]],'Вспомни слова без подсказок, затем проверь себя.'],['Повторение за диктором','Языки',20,2,[['Румынский язык',80],['Внимание',20]],'Повторяй короткую запись, следуя произношению и ритму.'],['Тренировка по боксу','Единоборства',60,3,[['Бокс',45],['Реакция',25],['Выносливость',20],['Дисциплина',10]],'Проведи тренировку в своём обычном безопасном темпе.'],['Прогулка в ровном темпе','Физические',40,1,[['Выносливость',70],['Дисциплина',30]],'Выдели время для прогулки без спешки.'],['Силовая тренировка','Физические',45,3,[['Сила',70],['Выносливость',20],['Дисциплина',10]],'Выполни свою привычную программу и запиши результат.'],['Разбор киносцены','Творчество',30,2,[['Творчество',70],['Внимание',30]],'Проанализируй композицию, свет и драматургию одной сцены.'],['Сценарная практика','Творчество',45,3,[['Творчество',80],['Дисциплина',20]],'Напиши короткую сцену с ясной целью и конфликтом.'],['Актёрское упражнение','Творчество',20,2,[['Творчество',70],['Внимание',30]],'Прочитай один монолог с тремя разными намерениями.'],['Тренировка памяти','Мышление',10,1,[['Память',80],['Внимание',20]],'Пройди упражнение на память в лаборатории разума.'],['Тренировка реакции','Мышление',5,1,[['Реакция',80],['Внимание',20]],'Пройди одну серию из пяти попыток.'],['Логическая сессия','Мышление',15,2,[['Логика',80],['Внимание',20]],'Реши несколько задач и прочитай объяснения.'],['Вдумчивое чтение','Мышление',30,2,[['Внимание',50],['Память',30],['Дисциплина',20]],'Прочитай главу и запиши три мысли своими словами.'],['Спокойное дыхание','Личностные',10,1,[['Внимание',60],['Дисциплина',40]],'Посиди спокойно, наблюдая за естественным дыханием.'],['Осмысленный разговор','Личностные',20,2,[['Эмоциональный интеллект',70],['Внимание',30]],'Задай открытый вопрос и выслушай ответ, не перебивая.'],['Работа без отвлечений','Личностные',50,3,[['Внимание',60],['Дисциплина',40]],'Выбери один результат и посвяти ему сессию.'],['Вечернее восстановление','Физические',20,1,[['Дисциплина',50],['Внимание',50]],'Заверши дела, приглуши свет и подготовь спокойный вечер.'],['Заметка о новом знании','Мышление',15,1,[['Память',50],['Логика',50]],'Объясни новую идею простыми словами и приведи пример.']];
function presetMission(i){const p=PRESETS[i];return {title:p[0],category:p[1],duration:p[2],difficulty:p[3],description:p[5],date:today(),time:'',repeat:'none',priority:0,customXP:null,notes:'',weekdays:[],interval:1,allocations:p[4].map(([name,weight])=>{let a=state.attributes.find(a=>a.name===name&&!a.archived);if(!a){a=newAttribute(name,p[1],name==='Эмоциональный интеллект'?'brain':'target',ACCENTS[1]);state.attributes.push(a)}return {id:a.id,weight}})}}
function library(){Modal.open('Библиотека миссий',`<p class="muted small">Готовая основа для твоей миссии. Дату, сложность и награду можно изменить.</p><div class="toolbar space"><select id="preset-filter" aria-label="Категория библиотеки"><option value="all">Все направления</option>${CATEGORIES.map(c=>`<option>${c}</option>`).join('')}</select></div><div id="preset-list"></div>`,true);const list=()=>{$('#preset-list').innerHTML=PRESETS.map((p,i)=>({p,i})).filter(({p})=>$('#preset-filter').value==='all'||p[1]===$('#preset-filter').value).map(({p,i})=>`<div class="mission" style="padding:15px 0"><span class="skill-icon" style="--c:var(--accent)">${icon('book',17)}</span><div class="grow"><h3 style="font-size:14px">${p[0]}</h3><p class="dim small">${p[1]} · ${p[2]} мин · ${DIFFICULTIES[p[3]][0]}</p></div><button class="btn" data-action="add-preset" data-value="${i}">Выбрать</button></div>`).join('')};$('#preset-filter').onchange=list;list()}
const ROUTINE_PRESETS=[['Утренний протокол','Собери внимание перед началом дня.',[13,4,17]],['Языковой день','Новые слова, живая речь и повторение.',[0,1,2]],['Боевая подготовка','Техника, выносливость и реакция.',[3,10]],['Режиссёрская практика','От наблюдения — к собственной сцене.',[6,7,8]],['Ясность мышления','Короткая сессия для памяти и логики.',[9,11,12]],['Глубокая работа','Внимание и ритм для важного результата.',[13,15]]];
function renderRoutines(){return intro('Твои протоколы','Повторяемые последовательности для устойчивого развития.',`<button class="btn primary" data-action="new-routine">${icon('plus',16)}Новый протокол</button>`)+(state.routines.length?`<div class="cards">${state.routines.slice().sort((a,b)=>Number(b.favorite)-Number(a.favorite)).map(r=>`<section class="panel pad"><div class="flex between"><span class="skill-icon" style="--c:var(--gold)">${icon('routine')}</span><button class="icon-btn ${r.favorite?'gold':''}" data-action="favorite-routine" data-id="${r.id}" aria-label="${r.favorite?'Убрать из избранного':'В избранное'}">${icon('award',18)}</button></div><h3 class="space">${esc(r.name)}</h3><p>${esc(r.description||'Твой личный порядок действий.')}</p><div class="dim small" style="margin-bottom:18px">${r.missions.length} миссий · ${r.missions.reduce((s,m)=>s+m.duration,0)} мин</div><div class="flex wrap"><button class="btn primary" data-action="activate-routine" data-id="${r.id}">Активировать</button><button class="icon-btn" data-action="edit-routine" data-id="${r.id}" aria-label="Изменить протокол">${icon('edit')}</button><button class="icon-btn" data-action="duplicate-routine" data-id="${r.id}" aria-label="Копировать протокол">${icon('copy')}</button><button class="icon-btn" data-action="delete-routine" data-id="${r.id}" aria-label="Удалить протокол">${icon('trash')}</button></div></section>`).join('')}</div>`:'')+`<h2 class="space" style="margin-bottom:18px">Готовые протоколы</h2><div class="cards">${ROUTINE_PRESETS.map((r,i)=>`<section class="panel pad"><span class="eyebrow">${r[2].length} МИССИИ</span><h3 style="margin-top:15px">${r[0]}</h3><p>${r[1]}</p><button class="btn" data-action="use-routine-preset" data-value="${i}">${icon('plus',15)}Добавить к себе</button></section>`).join('')}</div>`}
function routineForm(id){const r=state.routines.find(r=>r.id===id);Modal.open(r?'Изменить протокол':'Новый протокол',`<form id="routine-form"><div class="stack"><label class="field">Название<input name="name" required maxlength="100" value="${esc(r?.name||'')}" placeholder="Например, вечерний протокол"></label><label class="field">Описание<textarea name="description" maxlength="2000">${esc(r?.description||'')}</textarea></label><div><h3>Миссии в протоколе</h3><p class="field-hint">Выбери свои миссии. В протокол сохранятся их независимые копии.</p><div id="routine-choices" class="stack" style="gap:8px;margin-top:12px">${r?.missions.map((m,i)=>`<label class="flex small"><input type="checkbox" name="old" value="${i}" checked>${esc(m.title)}</label>`).join('')||''}${state.missions.filter(m=>!m.archived).map(m=>`<label class="flex small"><input type="checkbox" name="mission" value="${m.id}">${esc(m.title)}</label>`).join('')||(!r?'<p class="muted small">Сначала создай миссии или добавь готовый протокол.</p>':'')}</div></div></div><div class="error" id="routine-error"></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Отмена</button><button class="btn primary">Сохранить протокол</button></div></form>`);$('#routine-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),missions=[...f.getAll('old').map(i=>r.missions[+i]),...f.getAll('mission').map(id=>state.missions.find(m=>m.id===id))].map(m=>structuredClone(m));if(!missions.length)return $('#routine-error').textContent='Добавь хотя бы одну миссию.';const name=f.get('name').trim();if(!name)return;const item={id:r?.id||uid(),name,description:f.get('description'),missions,favorite:r?.favorite||false,activations:r?.activations||[]};if(r)Object.assign(r,item);else state.routines.push(item);save();Modal.close();render();toast('Протокол сохранён')}}
function activateRoutine(id){const r=state.routines.find(r=>r.id===id);Modal.open('Активировать «'+r.name+'»',`<p class="muted">${r.missions.length} миссий будут добавлены на выбранный день.</p><label class="field space">Дата<input id="routine-date" type="date" value="${today()}"></label><div class="error" id="routine-error"></div><div class="modal-actions"><button class="btn" data-action="close-modal">Отмена</button><button class="btn primary" id="activate-now">Добавить в расписание</button></div>`);$('#activate-now').onclick=()=>{const date=$('#routine-date').value;if(!validDate(date))return $('#routine-error').textContent='Выбери корректную дату.';if(r.activations.includes(date))return $('#routine-error').textContent='Этот протокол уже активирован на выбранную дату.';state.missions.push(...r.missions.map(m=>({...structuredClone(m),id:uid(),date,repeat:'none',archived:false})));r.activations.push(date);addActivity('Активирован протокол «'+r.name+'»','routine');save();Modal.close();render();toast('Протокол добавлен в расписание')}}
// ── Onboarding: no fabricated progress ──────────────────────────────────
function onboarding(){const step=onboardingStep;Modal.open('Добро пожаловать в SANCTUM',`<div class="onboard"><div class="onboard-steps">${[0,1,2].map(i=>`<i class="${i<=step?'active':''}"></i>`).join('')}</div>${step===0?`${mark}<h2>Это твоё пространство.</h2><p>Место, где реальные действия становятся частью того, кем ты хочешь быть.</p><label class="field">Как к тебе обращаться?<input id="onboard-name" maxlength="60" value="${esc(onboardingName)}" placeholder="Имя или позывной" autocomplete="off"></label>`:step===1?`<h2>Выбери направления.</h2><p>Начни с важного. Любой атрибут можно добавить или изменить позже.</p><div class="starter-choices">${state.attributes.map((a,i)=>`<label><input type="checkbox" name="starter" value="${a.id}" ${i<7?'checked':''}>${esc(a.name)}</label>`).join('')}</div>`:`<h2>Первый шаг — сегодня.</h2><p>Достаточно одной небольшой миссии, чтобы начать.</p><label class="field">Твоя первая миссия<input id="first-mission" maxlength="160" value="30 минут на важное"></label><label class="field space">Какой атрибут развиваем?<select id="first-skill">${state.attributes.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></label>`}<div class="error" id="onboard-error"></div><div class="modal-actions"><button class="btn ghost" id="quick-start">Быстрый старт</button><button class="btn primary" id="onboard-next">${step===2?'Войти в SANCTUM':'Продолжить'} ${icon('arrow',15)}</button></div><p class="field-hint" style="margin:18px auto 0">Без регистрации. Все данные хранятся у тебя.</p></div>`);$('#quick-start').onclick=()=>{if(step===0)state.profile.name=$('#onboard-name').value.trim()||'Исследователь';state.profile.onboarded=true;save();Modal.close();render();toast('Добро пожаловать. Начни со своей первой миссии.')};$('#onboard-next').onclick=()=>{if(step===0){onboardingName=$('#onboard-name').value.trim()||'Исследователь';state.profile.name=onboardingName;onboardingStep=1;onboarding()}else if(step===1){const selected=$$('input[name=starter]:checked').map(x=>x.value);if(!selected.length)return $('#onboard-error').textContent='Выбери хотя бы один атрибут.';state.attributes=state.attributes.filter(a=>selected.includes(a.id));onboardingStep=2;onboarding()}else{const title=$('#first-mission').value.trim();if(!title)return $('#onboard-error').textContent='Назови первый шаг или выбери быстрый старт.';state.missions.push({id:uid(),title,description:'',date:today(),time:'',duration:30,difficulty:2,repeat:'none',weekdays:[],interval:1,category:state.attributes.find(a=>a.id===$('#first-skill').value).category,customXP:null,priority:0,notes:'',archived:false,createdAt:new Date().toISOString(),allocations:[{id:$('#first-skill').value,weight:100}]});state.profile.onboarded=true;addActivity('Твоя первая миссия готова','mission');save();Modal.close();render();toast('Первый шаг запланирован. Добро пожаловать в SANCTUM.')}}}

// Configurable development profile and level ranks.
const DEFAULT_RANKS=[{level:1,name:'Новичок'},{level:3,name:'Искатель'},{level:5,name:'Практик'},{level:10,name:'Специалист'},{level:15,name:'Эксперт'},{level:20,name:'Мастер'},{level:30,name:'Наставник'},{level:50,name:'Архитектор'},{level:75,name:'Визионер'},{level:100,name:'Легенда'}];
function rankFor(level=XPSystem.level(totalXP()).level){return (state.profile.ranks||DEFAULT_RANKS).filter(r=>r.level<=level).at(-1)?.name||'Новичок'}
function rankEditor(){let rows=structuredClone(state.profile.ranks||DEFAULT_RANKS);Modal.open('Названия уровней',`<p class="muted small">Название действует с указанного уровня до следующей ступени. Можно переименовать ступени и добавить собственные.</p><form id="rank-form"><div id="rank-rows" class="space"></div><button type="button" class="btn ghost" id="rank-add">${icon('plus',15)}Добавить ступень</button><div class="error" id="rank-error" role="alert"></div><div class="modal-actions"><button class="btn" type="button" id="rank-defaults">Стандартные названия</button><button class="btn primary">Сохранить</button></div></form>`);const read=()=>rows=$$('[data-rank-row]').map(el=>({level:Number($('input[type=number]',el).value),name:$('input[type=text]',el).value.trim()}));const draw=()=>{$('#rank-rows').innerHTML=rows.map((r,i)=>`<div class="rank-row" data-rank-row><label class="field">С уровня<input type="number" min="1" max="10000" step="1" required value="${r.level}" aria-label="Уровень ступени ${i+1}"></label><label class="field">Название<input type="text" required maxlength="60" value="${esc(r.name)}" aria-label="Название ступени ${i+1}"></label><button type="button" class="icon-btn" data-rank-remove="${i}" aria-label="Убрать ступень ${i+1}">${icon('close',16)}</button></div>`).join('');$$('[data-rank-remove]').forEach(b=>b.onclick=()=>{read();rows.splice(+b.dataset.rankRemove,1);draw()})};draw();$('#rank-add').onclick=()=>{read();if(rows.length>=30)return toast('Можно настроить до 30 ступеней.');rows.push({level:Math.min(10000,Math.max(0,...rows.map(r=>r.level))+5),name:''});draw()};$('#rank-defaults').onclick=()=>{rows=structuredClone(DEFAULT_RANKS);draw()};$('#rank-form').onsubmit=e=>{e.preventDefault();read();rows.sort((a,b)=>a.level-b.level);if(!rows.length||rows[0].level!==1||new Set(rows.map(r=>r.level)).size!==rows.length||rows.some(r=>!r.name||!Number.isInteger(r.level)||r.level<1||r.level>10000))return $('#rank-error').textContent='Начни с уровня 1. У каждой ступени должны быть название и уникальный целый уровень.';state.profile.ranks=rows;save();Modal.close();render();toast('Названия уровней сохранены')}}
const CHART_DEFAULTS={view:'radar',metric:'xp',group:'attributes',period:'all',axes:[]};
function chartPrefs(){return {...CHART_DEFAULTS,...state.settings.developmentChart}}
function developmentData(){const p=chartPrefs(),from=p.period==='week'?weekStart():p.period==='month'?today().slice(0,8)+'01':'2000-01-01';const records=[...state.completions,...state.brain.sessions].filter(r=>r.date>=from&&r.date<=today());let rows=state.attributes.filter(a=>!a.archived).map(a=>({id:a.id,name:a.name,color:a.accent,category:a.category,value:0}));for(const r of records){const sum=r.allocations.reduce((n,a)=>n+a.xp,0);for(const x of r.allocations){const a=rows.find(a=>a.id===x.id);if(a&&x.xp>0)a.value+=p.metric==='xp'?x.xp:p.metric==='sessions'?1:(sum?r.duration*x.xp/sum:0)}}if(p.group==='categories')rows=CATEGORIES.map((name,i)=>({id:name,name,color:ACCENTS[i%6],value:p.metric==='sessions'?records.filter(r=>r.allocations.some(x=>x.xp>0&&rows.some(a=>a.id===x.id&&a.category===name))).length:rows.filter(a=>a.category===name).reduce((n,a)=>n+a.value,0)})).filter(r=>state.attributes.some(a=>!a.archived&&a.category===r.name));const sorted=rows.slice().sort((a,b)=>b.value-a.value);return {all:rows,shown:p.axes.length?rows.filter(r=>p.axes.includes(r.id)):sorted.slice(0,8),p,from}}
function developmentChart(){const {all,shown:rows,p}=developmentData(),max=Math.max(1,...rows.map(r=>r.value)),unit=p.metric==='xp'?'ОП':p.metric==='sessions'?'занятий':'мин',fmt=v=>number(Math.round(v*10)/10),scale=Math.max(1,Math.ceil(max/5)*5);let chart='';if(!rows.length)chart='<div class="empty"><h3>Нет направлений для сравнения</h3><p>Добавь атрибуты или измени выбор показателей.</p></div>';else if(p.view==='radar'&&rows.length>=3){const n=rows.length,point=(i,r)=>{const angle=i*2*Math.PI/n-Math.PI/2;return [260+Math.cos(angle)*r,205+Math.sin(angle)*r]},points=r=>rows.map((_,i)=>point(i,r).join(',')).join(' ');chart=`<svg class="radar-chart" viewBox="0 0 520 420" role="img" aria-label="Паутина развития: ${esc(rows.map(r=>r.name+' — '+fmt(r.value)+' '+unit).join('; '))}"><defs><radialGradient id="radar-fill"><stop offset="0" stop-color="#a7cdc9" stop-opacity=".06"/><stop offset="1" stop-color="#a7cdc9" stop-opacity=".32"/></radialGradient></defs>${[1,2,3,4,5].map(k=>`<polygon points="${points(k*27)}" fill="${k===5?'#a7cdc905':'none'}" stroke="#3b4d50" stroke-dasharray="${k===5?'none':'2 5'}"/><text x="267" y="${205-k*27-4}" class="radar-scale">${fmt(scale*k/5)}</text>`).join('')}${rows.map((r,i)=>{const [x,y]=point(i,135),[lx,ly]=point(i,172);const label=r.name.length>19?r.name.slice(0,17)+'…':r.name;return `<line x1="260" y1="205" x2="${x}" y2="${y}" stroke="#324447"/><text x="${lx}" y="${ly}" text-anchor="middle" class="radar-label"><title>${esc(r.name)}</title>${esc(label)}</text><text x="${lx}" y="${ly+18}" text-anchor="middle" class="radar-value">${fmt(r.value)} ${unit}</text>`}).join('')}<polygon points="${rows.map((r,i)=>point(i,r.value/scale*135).join(',')).join(' ')}" fill="url(#radar-fill)" stroke="#a7cdc9" stroke-width="2" stroke-linejoin="round"/>${rows.map((r,i)=>{const [x,y]=point(i,r.value/scale*135);return `<circle cx="${x}" cy="${y}" r="4" fill="#c9e5de"><title>${esc(r.name)}: ${fmt(r.value)} ${unit}</title></circle>`}).join('')}</svg>`}else if(p.view==='cards'){chart=`<div class="indicator-cards">${rows.map(r=>`<div class="indicator-card" style="--c:${r.color}"><span class="muted small">${esc(r.name)}</span><strong>${fmt(r.value)} <small>${unit}</small></strong><div class="bar" style="--p:${r.value/max*100}%"><i></i></div></div>`).join('')}</div>`}else{chart=`${p.view==='radar'?'<p class="field-hint" style="margin-bottom:20px">Для паутины нужны минимум три направления. Пока показаны столбцы.</p>':''}<div class="distribution">${rows.map(r=>`<div class="dev-bar-row"><div class="flex between"><span>${esc(r.name)}</span><strong style="color:${r.color}">${fmt(r.value)} <small>${unit}</small></strong></div><div class="bar" style="--p:${r.value/max*100}%;--c:${r.color};height:8px;margin-top:9px"><i></i></div></div>`).join('')}</div>`}return `<section class="panel pad development-panel"><div class="flex between wrap"><div><div class="eyebrow">БАЛАНС РАЗВИТИЯ</div><h2 style="margin-top:7px">Твой профиль в движении</h2></div><div class="chart-switch" role="group" aria-label="Вид диаграммы">${[['radar','Паутина','skills'],['bars','Столбцы','chart'],['cards','Карточки','grid']].map(([v,t,ic])=>`<button class="btn ${p.view===v?'primary':'ghost'}" data-chart-view="${v}" aria-pressed="${p.view===v}">${icon(ic,15)}${t}</button>`).join('')}</div></div><div class="chart-controls space"><label class="field">Показатель<select data-chart-pref="metric">${[['xp','Полученный опыт'],['sessions','Количество занятий'],['minutes','Время развития']].map(([v,t])=>`<option value="${v}" ${p.metric===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Сравнивать<select data-chart-pref="group"><option value="attributes" ${p.group==='attributes'?'selected':''}>Атрибуты</option><option value="categories" ${p.group==='categories'?'selected':''}>Категории</option></select></label><label class="field">Период<select data-chart-pref="period">${[['all','Всё время'],['week','Эта неделя'],['month','Этот месяц']].map(([v,t])=>`<option value="${v}" ${p.period===v?'selected':''}>${t}</option>`).join('')}</select></label><button class="btn" id="chart-axes">${icon('settings',15)}Направления</button></div><div class="development-layout"><div class="development-visual">${chart}</div><aside class="development-legend"><span class="eyebrow">${p.axes.length?'ТВОЙ ВЫБОР':'ВЕДУЩИЕ НАПРАВЛЕНИЯ'}</span>${rows.map((r,i)=>`<div class="legend-row"><span class="dim mono">${String(i+1).padStart(2,'0')}</span><span class="grow">${esc(r.name)}</span><strong>${fmt(r.value)}<small class="dim"> ${unit}</small></strong></div>`).join('')}<p class="field-hint space">${p.axes.length?'Выбрано':'Показано'} ${rows.length} из ${all.length}. ${p.axes.length?'':'Автоматически выбраны до восьми ведущих направлений.'} Масштаб относительный: сравнивай распределение усилий, а не предел своих возможностей.</p>${p.metric==='minutes'?'<p class="field-hint">Время делится между атрибутами пропорционально полученному опыту.</p>':''}${rows.every(r=>!r.value)?'<p class="accent small space">Первые действия придадут форму твоему профилю.</p>':''}</aside></div></section>`}
function chartAxesEditor(){const {all,p}=developmentData();Modal.open('Направления на диаграмме',`<p class="muted small">Выбери до восьми направлений. Без ручного выбора показываются ведущие по выбранному показателю.</p><form id="axes-form"><div class="starter-choices space">${all.map(a=>`<label><input type="checkbox" name="axis" value="${esc(a.id)}" ${p.axes.includes(a.id)?'checked':''}>${esc(a.name)}</label>`).join('')}</div><div class="error" id="axes-error" role="alert"></div><div class="modal-actions"><button class="btn" type="button" id="axes-auto">Выбирать автоматически</button><button class="btn primary">Применить</button></div></form>`);const apply=axes=>{state.settings.developmentChart={...p,axes};save();Modal.close();render()};$('#axes-auto').onclick=()=>apply([]);$('#axes-form').onsubmit=e=>{e.preventDefault();const axes=new FormData(e.target).getAll('axis');if(axes.length>8)return $('#axes-error').textContent='Оставь не больше восьми направлений — так подписи останутся читаемыми.';apply(axes)}}
function bindDevelopment(){const update=patch=>{state.settings.developmentChart={...chartPrefs(),...patch};save();render()};$$('[data-chart-view]').forEach(b=>b.onclick=()=>update({view:b.dataset.chartView}));$$('[data-chart-pref]').forEach(el=>el.onchange=()=>update({[el.dataset.chartPref]:el.value,...(el.dataset.chartPref==='group'?{axes:[]}: {})}));if($('#chart-axes'))$('#chart-axes').onclick=chartAxesEditor;if($('#edit-ranks'))$('#edit-ranks').onclick=rankEditor}

// ── Achievements and analytics ──────────────────────────────────────────
