function activityChart(){const start=addDays(today(),-6),values=Array.from({length:7},(_,i)=>({date:addDays(start,i),xp:periodXP(addDays(start,i),addDays(start,i))})),max=Math.max(100,...values.map(v=>v.xp));return `<svg class="chart" viewBox="0 0 560 190" role="img" aria-label="Опыт за последние семь дней: ${values.map(v=>`${fmtDate(v.date,true)} — ${v.xp}`).join(', ')}">${[0,1,2,3].map(i=>`<line x1="34" x2="550" y1="${155-i*44}" y2="${155-i*44}" stroke="#2a3639" stroke-dasharray="3 5"/><text x="0" y="${159-i*44}">${Math.round(max*i/3)}</text>`).join('')}${values.map((v,i)=>{const h=v.xp/max*132;return `<rect x="${56+i*72}" y="${155-Math.max(2,h)}" width="31" height="${Math.max(2,h)}" rx="3" fill="${i===6?'#a7cdc9':'#446965'}"/><text x="${71+i*72}" y="179" text-anchor="middle">${parseDate(v.date).toLocaleDateString('ru-RU',{weekday:'short'})}</text>${v.xp?`<text x="${71+i*72}" y="${146-h}" text-anchor="middle">${v.xp}</text>`:''}`}).join('')}</svg>`}
