output.missions=unique(arr(raw.missions,50000).map(mission));output.routines=unique(arr(raw.routines,10000).map(r=>({id:id(r.id),name:text(r.name,100),description:text(r.description||'',2000),favorite:bool(r.favorite||false),activations:arr(r.activations||[]).map(date),missions:arr(r.missions,1000).map(mission)})));
const allocations=rows=>arr(rows,10000).map(a=>({id:id(a.id),xp:num(a.xp,0,10000)}));const completionRecord=c=>{const xp=num(c.xp,0,10000),al=allocations(c.allocations);if(!Number.isInteger(xp)||al.some(a=>!Number.isInteger(a.xp))||al.reduce((n,a)=>n+a.xp,0)!==xp)fail('Сумма распределения не совпадает с наградой.');if(new Set(al.map(a=>a.id)).size!==al.length)fail();return {id:id(c.id),date:date(c.date),time:iso(c.time),title:text(c.title,300),xp,allocations:al,duration:num(c.duration,0,1440)}};
